const files={"src/app/embed/debroglie/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DeBroglieCanvas } from '@/components/simulation/DeBroglieCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PARTICLES } from '@/lib/physics/debroglie';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DeBroglieEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [pIdx, setPIdx] = useState(() => Math.round(num(sp, 'p', 0, 0, PARTICLES.length - 1)));\n  const particle = PARTICLES[pIdx];\n  const [velocity, setVelocity] = useState(() => num(sp, 'v', particle.vDefault, particle.vMin, particle.vMax));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [pIdx, velocity, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DeBroglieCanvas mass={particle.mass} velocity={velocity} particleName={particle.name}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.2857142857142856, 1.6) : 2.2857142857142856))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"flex flex-wrap gap-1.5\">\n            {PARTICLES.map((p, i) => (\n              <button key={p.name} onClick={() => { setPIdx(i); setVelocity(p.vDefault); }}\n                className={`rounded-full border px-2.5 py-1 text-[11px] font-medium transition ${\n                  pIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{p.emoji} {p.name}</button>\n            ))}\n          </div>\n          <Slider label=\"Speed\" unit=\"m/s\" value={velocity} min={particle.vMin} max={particle.vMax}\n            step={(particle.vMax - particle.vMin) / 200} set={setVelocity} color=\"#6366f1\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DeBroglieEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DeBroglieEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/quantum-harmonic-oscillator/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef, useMemo } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { QuantumHarmonicOscillatorCanvas } from '@/components/simulation/QuantumHarmonicOscillatorCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { QHOParams, normalize } from '@/lib/physics/quantumHarmonicOscillator';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key);\n  return v !== null ? v === '1' : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"font-normal text-gray-400\">{unit}</span>\n        </span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={(e) => set(Number(e.target.value))}\n        className=\"w-full\"\n        style={{ accentColor: color }}\n      />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction QuantumHOEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [c0, setC0] = useState(() => num(sp, 'c0', 1, 0, 1));\n  const [c1, setC1] = useState(() => num(sp, 'c1', 0, 0, 1));\n  const [c2, setC2] = useState(() => num(sp, 'c2', 0, 0, 1));\n  const [c3, setC3] = useState(() => num(sp, 'c3', 0, 0, 1));\n  const [c4, setC4] = useState(() => num(sp, 'c4', 0, 0, 1));\n  const [c5, setC5] = useState(() => num(sp, 'c5', 0, 0, 1));\n\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [xMax, setXMax] = useState(() => num(sp, 'xmax', 5, 3, 12));\n  const [eMax, setEMax] = useState(() => num(sp, 'emax', 4.5, 2, 8));\n  const [nMax, setNMax] = useState(() => num(sp, 'nmax', 5, 1, 8));\n\n  const [showPotential, setShowPotential] = useState(() => bool(sp, 'potential', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showReal, setShowReal] = useState(() => bool(sp, 'real', false));\n  const [showImaginary, setShowImaginary] = useState(() => bool(sp, 'imag', false));\n  const [showClassicalTurning, setShowClassicalTurning] = useState(() => bool(sp, 'turning', true));\n\n  const coeffs = useMemo(() => normalize([c0, c1, c2, c3, c4, c5]), [c0, c1, c2, c3, c4, c5]);\n\n  const params: QHOParams = {\n    speed,\n    xMax,\n    eMax,\n    nMax,\n    showPotential,\n    showEnergyLevels,\n    showProbability,\n    showReal,\n    showImaginary,\n    showClassicalTurning,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => {\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey((k) => k + 1);\n  }, []);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><QuantumHarmonicOscillatorCanvas\n        key={resetKey}\n        coeffs={coeffs}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        width={Math.max(160, embedSize.width - 24)}\n        height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(1.6, 1.6) : 1.6))}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls\n        isRunning={isRunning}\n        isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused((p) => !p)}\n        onReset={reset}\n      /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"c₀\" unit=\"\" value={c0} min={0} max={1} step={0.01} set={setC0} color=\"#6366f1\" />\n          <Slider label=\"c₁\" unit=\"\" value={c1} min={0} max={1} step={0.01} set={setC1} color=\"#8b5cf6\" />\n          <Slider label=\"c₂\" unit=\"\" value={c2} min={0} max={1} step={0.01} set={setC2} color=\"#ec4899\" />\n          <Slider label=\"c₃\" unit=\"\" value={c3} min={0} max={1} step={0.01} set={setC3} color=\"#f43f5e\" />\n          <Slider label=\"c₄\" unit=\"\" value={c4} min={0} max={1} step={0.01} set={setC4} color=\"#f59e0b\" />\n          <Slider label=\"c₅\" unit=\"\" value={c5} min={0} max={1} step={0.01} set={setC5} color=\"#10b981\" />\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"X-range\" unit=\"a\" value={xMax} min={3} max={12} step={0.5} set={setXMax} color=\"#10b981\" />\n          <Slider label=\"E-range\" unit=\"ℏω\" value={eMax} min={2} max={8} step={0.5} set={setEMax} color=\"#ef4444\" />\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showPotential} onChange={(e) => setShowPotential(e.target.checked)} className=\"rounded\" />\n              Potential\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergyLevels} onChange={(e) => setShowEnergyLevels(e.target.checked)} className=\"rounded\" />\n              Levels\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showProbability} onChange={(e) => setShowProbability(e.target.checked)} className=\"rounded\" />\n              |ψ|²\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showReal} onChange={(e) => setShowReal(e.target.checked)} className=\"rounded\" />\n              Re(ψ)\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showImaginary} onChange={(e) => setShowImaginary(e.target.checked)} className=\"rounded\" />\n              Im(ψ)\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showClassicalTurning} onChange={(e) => setShowClassicalTurning(e.target.checked)} className=\"rounded\" />\n              Turning pts\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function QuantumHOEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <QuantumHOEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/unit-circle/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useRef, useCallback, useEffect } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport '@/components/simulation/unit-circle.css';\nimport { UnitCircleCanvas } from '@/components/simulation/UnitCircleCanvas';\nimport { UnitCircleGraph } from '@/components/simulation/UnitCircleGraph';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { deg2rad, rad2deg, quadrantOf } from '@/lib/physics/unitCircle';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\n// Supported query params:\n//   angleDeg=150   starting angle in degrees (0-360)\n//   unit=rad       show the readout in radians instead of degrees\n//   graph=0        hide the sin/cos graphs\n//   controls=0     lock the embed at the given angle (no dragging, slider or animate) —\n//                  handy for worksheets that need to show one specific angle\nfunction UnitCircleEmbedInner() {\n  const sp = useSearchParams();\n  const showGraph = sp.get('graph') !== '0';\n  const showControls = sp.get('controls') !== '0';\n\n  const [angleDeg, setAngleDeg] = useState(() => num(sp, 'angleDeg', 45, 0, 360));\n  const [unit, setUnit] = useState<'deg' | 'rad'>(sp.get('unit') === 'rad' ? 'rad' : 'deg');\n  const [animating, setAnimating] = useState(false);\n  const animRef = useRef<number>(0);\n  const lastTsRef = useRef<number | null>(null);\n\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 420, 420, 420);\n\n  const toggleAnimate = useCallback(() => {\n    if (animating) {\n      cancelAnimationFrame(animRef.current);\n      setAnimating(false);\n      lastTsRef.current = null;\n      return;\n    }\n    setAnimating(true);\n    const step = (ts: number) => {\n      if (lastTsRef.current !== null) {\n        const dt = (ts - lastTsRef.current) / 1000;\n        setAngleDeg(prev => (prev + dt * 60) % 360);\n      }\n      lastTsRef.current = ts;\n      animRef.current = requestAnimationFrame(step);\n    };\n    animRef.current = requestAnimationFrame(step);\n  }, [animating]);\n\n  useEffect(() => () => cancelAnimationFrame(animRef.current), []);\n\n  const rad = deg2rad(angleDeg);\n  const sinVal = Math.sin(rad), cosVal = Math.cos(rad);\n  const quadrant = ['', 'I', 'II', 'III', 'IV'][quadrantOf(angleDeg)];\n  const thetaText = unit === 'deg' ? `${angleDeg.toFixed(2)}°` : `${rad.toFixed(3)} rad`;\n  const sliderMax = unit === 'deg' ? 360 : 2 * Math.PI;\n  const sliderValue = unit === 'deg' ? angleDeg : rad;\n  const reset = () => { cancelAnimationFrame(animRef.current); setAnimating(false); lastTsRef.current = null; setAngleDeg(num(sp, 'angleDeg', 45, 0, 360)); };\n\n  return (\n    <SimulationStage className=\"af-embed-stage af-unit-circle-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"flex min-w-0 justify-center rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n        <UnitCircleCanvas angleDeg={angleDeg} onAngleChange={showControls ? setAngleDeg : () => {}}\n          width={size.width} height={size.height} />\n      </div>\n\n      {showControls && <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n        <SimulationControls isRunning={animating} isPaused={false} onRun={toggleAnimate} onPause={toggleAnimate} onReset={reset} />\n        <div className=\"flex overflow-hidden rounded-lg border border-gray-200 text-xs\" role=\"group\" aria-label=\"Angle unit\">\n          <button onClick={() => setUnit('deg')} aria-pressed={unit==='deg'} className={`px-3 py-2 font-medium ${unit === 'deg' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-600'}`}>Degrees</button>\n          <button onClick={() => setUnit('rad')} aria-pressed={unit==='rad'} className={`px-3 py-2 font-medium ${unit === 'rad' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-600'}`}>Radians</button>\n        </div>\n      </div>}\n\n      {showControls && <div data-stage-role=\"parameters\" className=\"af-unit-angle rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n        <div className=\"flex items-center gap-3\">\n          <span className=\"w-14 shrink-0 text-xs text-gray-500\">θ ({unit === 'deg' ? '°' : 'rad'})</span>\n          <input type=\"range\" min={0} max={sliderMax} step={sliderMax / 720} value={sliderValue}\n            onChange={e => setAngleDeg(unit === 'deg' ? Number(e.target.value) : rad2deg(Number(e.target.value)))}\n            className=\"min-w-0 flex-1\" style={{accentColor:'#6366f1'}} aria-label={`Angle in ${unit === 'deg' ? 'degrees' : 'radians'}`} />\n          <output className=\"af-unit-angle-output text-right font-mono text-xs text-gray-700\">{thetaText}</output>\n        </div>\n      </div>}\n\n      <div data-stage-role=\"extra\" className=\"grid grid-cols-2 gap-2 rounded-2xl border border-gray-200 bg-white p-3 text-xs sm:grid-cols-4\">\n        {[\n          { l: 'θ', v: thetaText, c: 'text-indigo-600' },\n          { l: 'Quadrant', v: quadrant, c: 'text-gray-700' },\n          { l: 'sin θ', v: sinVal.toFixed(3), c: 'text-rose-600' },\n          { l: 'cos θ', v: cosVal.toFixed(3), c: 'text-amber-600' },\n        ].map(r => <div key={r.l} className=\"flex justify-between gap-2 rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">{r.l}</span><span className={`font-semibold tabular-nums ${r.c}`}>{r.v}</span></div>)}\n      </div>\n      {showGraph && <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-3\"><UnitCircleGraph angleDeg={angleDeg} /></div>}\n      <p data-stage-role=\"extra\" className=\"text-center text-[10px] text-gray-500\">A-Factor STEM Studio · Unit circle explorer</p>\n    </SimulationStage>\n  );\n}\n\nexport default function UnitCircleEmbedPage() {\n  // useSearchParams() needs a Suspense boundary in the App Router, or the\n  // build fails during static prerendering.\n  return (\n    <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}>\n      <UnitCircleEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/space/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { SpaceCanvas } from '@/components/simulation/SpaceCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { type Dim, type P3, type View, DEFAULT_VIEW, LABELS, P, RANGE, analyseJourney, clampDim, clampTo, coordText, fmt, len } from '@/lib/physics/space';\n\n// Parses \"x,y,z;x,y,z\" and clamps every value so a hand-edited URL can't break the simulation.\nfunction parsePoints(raw: string | null, dim: Dim): P3[] {\n  const r = RANGE[dim];\n  const pts = (raw ?? '').split(';').slice(0, 5).map(t => { const [x, y, z] = t.split(',').map(Number); return clampDim(P(clampTo(Number.isFinite(x) ? x : 0, r), clampTo(Number.isFinite(y) ? y : 0, r), clampTo(Number.isFinite(z) ? z : 0, r)), dim); });\n  return pts.length ? pts : [P(3, 2, 4)].map(p => clampDim(p, dim));\n}\n\nfunction SpaceEmbedInner() {\n  const sp = useSearchParams();\n  const dim: Dim = sp.get('dim') === '1d' ? '1d' : sp.get('dim') === '2d' ? '2d' : '3d';\n  const act = sp.get('act') === 'journey' ? 'journey' : 'locate';\n  const [pts, setPts] = useState<P3[]>(() => { const p = parsePoints(sp.get('pts'), dim); return act === 'journey' && p.length < 2 ? [P(0, 0, 0), ...p] : p; });\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const [sel, setSel] = useState(0);\n  const J = analyseJourney(pts, dim);\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 640, dim === '3d' ? 420 : 380, 900);\n  const width = size.width, height = width < 560 ? Math.round(width * (dim === '1d' ? 0.62 : 1.0)) : size.height;\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-xl border border-gray-200 p-1\">\n        <SpaceCanvas dim={dim} activity={act} width={width} height={height} points={act === 'journey' ? pts : [pts[0]]} labels={act === 'journey' ? LABELS : ['P']}\n          selected={sel} onMove={(i, p) => setPts(s => s.map((q, k) => (k === i ? p : q)))} onSelect={setSel} snap={1} view={view} onView={setView} dragAxis=\"floor\"\n          showPlanes showGrid showGuides showComponents />\n      </div>\n      <div data-stage-role=\"extra\" className=\"mt-2 grid gap-2 text-xs sm:grid-cols-2\">\n        {act === 'locate' ? (\n          <>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Position </span><span className=\"font-semibold text-red-600\">{coordText(pts[0], dim)}</span></div>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Distance from O </span><span className=\"font-semibold text-indigo-600\">{fmt(len(pts[0]))}</span></div>\n          </>\n        ) : (\n          <>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Distance </span><span className=\"font-semibold text-indigo-600\">{fmt(J.distance)}</span></div>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">|Displacement| </span><span className=\"font-semibold text-rose-600\">{fmt(J.magnitude)}</span></div>\n          </>\n        )}\n      </div>\n      <div data-stage-role=\"extra\"><p className=\"mt-1.5 text-[10px] text-gray-400\">{dim === '3d' ? 'Drag empty space to rotate. ' : ''}Drag a point to move it. A-Factor STEM Studio</p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function SpaceEmbedPage() {\n  return <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}><SpaceEmbedInner /></Suspense>;\n}\n", "src/app/embed/magnetic-effects/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { MagneticFieldCanvas, MagneticMode } from '@/components/simulation/MagneticFieldCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'straight-wire' | 'solenoid' | 'motor-effect';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction MagneticEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'solenoid' || t === 'motor-effect' ? t : 'straight-wire';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [current, setCurrent] = useState(() => num(sp, 'current', 5, 1, 20));\n  const [currentOut, setCurrentOut] = useState(() => sp.get('out') !== '0');\n  const [turnsPerMetre, setTurnsPerMetre] = useState(() => num(sp, 'turns', 1000, 200, 3000));\n  const [fieldB, setFieldB] = useState(() => num(sp, 'field', 0.5, 0.1, 2));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, current, currentOut, turnsPerMetre, fieldB, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><MagneticFieldCanvas key={resetKey} mode={topic as MagneticMode} current={current} currentOut={currentOut}\n        turnsPerMetre={turnsPerMetre} fieldB={fieldB}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Current\" unit=\"A\" value={current} min={1} max={20} step={1} set={setCurrent} color=\"#6366f1\" />\n          <div className=\"flex gap-2\">\n            {([true, false] as const).map(v => (\n              <button key={String(v)} onClick={() => setCurrentOut(v)}\n                className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                  currentOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{v ? 'Out ⊙' : 'In ⊗'}</button>\n            ))}\n          </div>\n          {topic === 'solenoid' && (\n            <Slider label=\"Turns per metre\" unit=\"n/m\" value={turnsPerMetre} min={200} max={3000} step={100} set={setTurnsPerMetre} color=\"#f59e0b\" />\n          )}\n          {topic === 'motor-effect' && (\n            <Slider label=\"Field strength\" unit=\"T\" value={fieldB} min={0.1} max={2} step={0.1} set={setFieldB} color=\"#f59e0b\" />\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function MagneticEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <MagneticEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/polarization/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PolarizationCanvas, PolarizationMode } from '@/components/simulation/PolarizationCanvas';\nimport { SimulationControls } from '@/components/sim