lement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const mode = ((): WaveMode => {\n    const m = sp.get('mode');\n    return m === 'longitudinal' || m === 'superposition' || m === 'standing' ? m : 'transverse';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [A, setA] = useState(() => num(sp, 'A', 1, 0.2, 1.5));\n  const [f, setF] = useState(() => num(sp, 'f', 0.5, 0.1, 2));\n  const [lambda, setLambda] = useState(() => num(sp, 'lambda', 2, 0.5, 4));\n  const [A2, setA2] = useState(() => num(sp, 'A2', 0.7, 0.1, 1.5));\n  const [f2, setF2] = useState(() => num(sp, 'f2', 0.5, 0.1, 2));\n  const [phase2, setPhase2] = useState(() => num(sp, 'phase2', 0, 0, 360));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [A, f, lambda, A2, f2, phase2, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><WaveCanvas key={resetKey} mode={mode}\n        amplitude={A} frequency={f} wavelength={lambda}\n        amplitude2={A2} frequency2={f2} phase2={phase2}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.2, 1.6) : 2.2))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        on