rchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'ac-generator' || t === 'transformer' ? t : 'faraday-lenz';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [turns, setTurns] = useState(() => num(sp, 'turns', 8, 2, 20));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 2, 0.5, 5));\n  const [magnetPoleOut, setMagnetPoleOut] = useState(true);\n\n  const [genFieldB, setGenFieldB] = useState(0.3);\n  const [genArea] = useState(0.02);\n  const [genOmega, setGenOmega] = useState(3);\n\n  const [primaryTurns, setPrimaryTurns] = useState(500);\n  const [secondaryTurns, setSecondaryTurns] = useState(100);\n  const [primaryVoltage] = useState(240);\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, turns, speed, magnetPoleOut, genFieldB, genOmega, primaryTurns, secondaryTurns, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><InductionCanvas key={resetKey} mode={topic as InductionMode}\n        turns={turns} speed={speed} magnetPoleOut={magnetPoleOut}\n        fieldB={genFieldB} coilArea={genArea} omega={genOmega}\n        primaryTurns={primaryTurns} secondaryTurns={secondaryTurns} primaryVoltage={primaryVoltage}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'faraday-lenz' && <>\n            <Slider label=\"Coil turns\" unit=\"\" value={turns} min={2} max={20} step={1} set={setTurns} color=\"#6366f1\" />\n            <Slider label=\"Oscillation speed\" unit=\"rad/s\" value={speed} min={0.5} max={5} step={0.5} set={setSpeed} color=\"#f59e0b\" />\n            <div className=\"flex gap-2\">\n              {([true, false] as const).map(v => (\n                <button key={String(v)} onClick={() => setMagnetPoleOut(v)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    magnetPoleOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{v ? 'N faces coil' : 'S faces coil'}</button>\n              ))}\n            </div>\n          </>}\n          {topic === 'ac-generator' && <>\n            <Slider label=\"Field strength\" unit=\"T\" value={genFieldB} min={0.1} max={1} step={0.05} set={setGenFieldB} color=\"#f59e0b\" />\n            <Slider label=\"Angular speed\" unit=\"rad/s\" value={genOmega} min={1} max={10} step={0.5} set={setGenOmega} color=\"#8b5cf6\" />\n          </>}\n          {topic === 'transformer' && <>\n            <Slider label=\"Primary turns\" unit=\"\" value={primaryTurns} min={50} max={1000} step={50} set={setPrimaryTurns} color=\"#6366f1\" />\n            <Slider label=\"Secondary turns\" unit=\"\" value={secondaryTurns} min={50} max={1000} step={50} set={setSecondaryTurns} color=\"#2563eb\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function InductionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <InductionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/bjt-transistor/page.tsx": "// src/app/embed/bjt-transistor/page.tsx\n'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport BjtCanvas from '@/components/simulation/BjtCanvas';\nimport { BjtParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/bjtTransistor';\n\nexport default function BjtEmbedPage() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const [params, setParams] = useState<BjtParams>(getPreset('cutoff'));\n  const [activePreset, setActivePreset] = useState('cutoff');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage af-stage-dark mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n        <div data-stage-role=\"canvas\"><BjtCanvas params={params} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(1.6, 1.6) : 1.6))} /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}", "src/app/embed/reflection/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ReflectionCanvas, ReflectionMode } from '@/components/simulation/ReflectionCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ReflectionEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const mode = ((): ReflectionMode => {\n    const m = sp.get('mode');\n    return m === 'curved' || m === 'rotation' ? m : 'plane';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [incidenceAngle, setIncidenceAngle] = useState(() => num(sp, 'angle', 35, 5, 80));\n  const [focal, setFocal] = useState(() => num(sp, 'focal', 15, 5, 40));\n  const [objectDist, setObjectDist] = useState(() => num(sp, 'u', 40, 5, 90));\n  const [converging, setConverging] = useState(() => sp.get('conv') !== '0');\n  const [rotationAngle, setRotationAngle] = useState(() => num(sp, 'angle', 15, -35, 35));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, incidenceAngle, focal, objectDist, converging, rotationAngle, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ReflectionCanvas key={resetKey} mode={mode} incidenceAngle={incidenceAngle}\n        focal={focal} objectDist={objectDist} converging={converging}\n        rotationAngle={rotationAngle} isRunning={isRunning} isPaused={isPaused}\n        width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.0625, 1.6) : 2.0625))} /></div>\n      <div data-stage-role=\"playback\">{mode === 'rotation' && (\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n      )}</div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            {mode === 'plane' && (\n              <Slider label=\"Angle of incidence\" unit=\"°\" value={incidenceAngle} min={5} max={80} step={1} set={setIncidenceAngle} color=\"#6366f1\" />\n            )}\n            {mode === 'curved' && <>\n              <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n              <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\" />\n              <div className=\"space-y-1\">\n                <span className=\"text-xs text-gray-500\">Type</span>\n                <div className=\"flex gap-2\">\n                  {([true, false] as const).map(c => (\n                    <button key={String(c)} onClick={() => setConverging(c)}\n                      className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium transition ${\n                        converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>\n                      {c ? 'Concave' : 'Convex'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </>}\n            {mode === 'rotation' && (\n              <Slider label=\"Mirror rotation θ\" unit=\"°\" value={rotationAngle} min={-35} max={35} step={1} set={setRotationAngle} color=\"#6366f1\" />\n            )}\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ReflectionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ReflectionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/pn-junction/page.tsx": "// src/app/embed/pn-junction/page.tsx\n'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport PnJunctionCanvas from '@/components/simulation/PnJunctionCanvas';\nimport { MaterialParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/pnJunction';\n\nexport default function PnJunctionEmbedPage() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const [params, setParams] = useState<MaterialParams>(getPreset('equilibrium'));\n  const [activePreset, setActivePreset] = useState('equilibrium');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage af-stage-dark mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n        <div data-stage-role=\"canvas\"><PnJunctionCanvas params={params} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(1.6666666666666667, 1.6) : 1.6666666666666667))} /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}", "src/app/embed/vectors/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { VectorCanvas } from '@/components/simulation/VectorCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { type P3, type View, DEFAULT_VIEW, P, clampTo, fmt } from '@/lib/physics/space';\nimport { type VMode, add, angleBetween, compText, cross, dot, mag, minus, scale, sceneFor } from '@/lib/physics/vectors';\n\nconst MODES: VMode[] = ['components', 'add', 'scalar', 'dot', 'cross'];\n// \"x,y,z\" with every value clamped, so a hand-edited URL cannot break the simulation.\nconst vec = (raw: string | null, dim: '2d' | '3d', fallback: P3): P3 => {\n  if (!raw) return fallback;\n  const [x, y, z] = raw.split(',').map(Number);\n  const c = (n: number) => (Number.isFinite(n) ? clampTo(n, 40) : 0);\n  return P(c(x), c(y), dim === '3d' ? c(z) : 0);\n};\n\nfunction VectorsEmbedInner() {\n  const sp = useSearchParams();\n  const dim: '2d' | '3d' = sp.get('dim') === '3d' ? '3d' : '2d';\n  const m = sp.get('mode') as VMode | null;\n  const mode: VMode = m && MODES.includes(m) ? m : 'add';\n  const [A, setA] = useState<P3>(() => vec(sp.get('A'), dim, dim === '2d' ? P(3, 4) : P(3, 2, 1)));\n  const [B, setB] = useState<P3>(() => vec(sp.get('B'), dim, dim === '2d' ? P(-1, 2) : P(1, 3, 2)));\n  const k = Number.isFinite(Number(sp.get('k'))) ? clampTo(Number(sp.get('k')), 10) : 2;\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 640, dim === '3d' ? 420 : 400, 900);\n  const h = size.width < 560 ? Math.round(size.width) : size.height;\n  const scene = sceneFor(mode, dim, { A, B, C: P(), k, op: 'A+B', method: 'triangle', useC: false, showComponents: true, showUnit: false, showAngle: true });\n  const onHandle = (id: 'A' | 'B' | 'C', at: P3) => {\n    const hd = scene.handles.find(x => x.id === id); if (!hd) return;\n    const v = scale(minus(at, hd.base), hd.mul ?? 1);\n    if (id === 'A') setA(dim === '2d' ? P(v.x, v.y) : v); else if (id === 'B') setB(dim === '2d' ? P(v.x, v.y) : v);\n  };\n  const stat = (label: string, value: string) => <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">{label} </span><span className=\"font-semibold text-gray-900\">{value}</span></div>;\n  const ang = angleBetween(A, B);\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-xl border border-gray-200 p-1\">\n        <VectorCanvas dim={dim} width={size.width} height={h} scene={scene} snap={1} view={view} onView={setView} dragAxis=\"floor\" showPlanes showGrid onHandle={onHandle}\n          ariaLabel=\"Vector diagram. Drag the coloured dots at the vector tips.\" />\n      </div>\n      <div data-stage-role=\"extra\" className=\"mt-2 grid gap-2 text-xs sm:grid-cols-2\">\n        {mode === 'components' && <>{stat('|A|', fmt(mag(A)))}{stat('A', compText(A, dim))}</>}\n        {mode === 'add' && <>{stat('A + B', compText(add(A, B), dim))}{stat('|A + B|', fmt(mag(add(A, B))))}</>}\n        {mode === 'scalar' && <>{stat(`${fmt(k)}A`, compText(scale(A, k), dim))}{stat(`|${fmt(k)}A|`, fmt(mag(scale(A, k))))}</>}\n        {mode === 'dot' && <>{stat('A·B', fmt(dot(A, B)))}{stat('Angle', ang === null ? 'undefined' : `${fmt(ang, 1)}°`)}</>}\n        {mode === 'cross' && <>{stat('A × B', compText(cross(A, B), '3d'))}{stat('|A × B|', fmt(mag(cross(A, B))))}</>}\n      </div>\n      <div data-stage-role=\"extra\"><p className=\"mt-1.5 text-[10px] text-gray-400\">{dim === '3d' ? 'Drag empty space to rotate. ' : ''}Drag a coloured dot to change a vector. A-Factor STEM Studio</p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function VectorsEmbedPage() {\n  return <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}><VectorsEmbedInner /></Suspense>;\n}\n", "src/app/embed/photoelectric/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PhotoelectricCanvas } from '@/components/simulation/PhotoelectricCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { METALS } from '@/lib/physics/photoelectric';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction PhotoelectricEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [metalIdx, setMetalIdx] = useState(() => Math.round(num(sp, 'metal', 0, 0, METALS.length - 1)));\n  const [f14, setF14] = useState(() => num(sp, 'f', 6, 2, 14));\n  const [intensity, setIntensity] = useState(() => num(sp, 'i', 5, 1, 10));\n  const metal = METALS[metalIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [metalIdx, f14, intensity, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><PhotoelectricCanvas f14={f14} intensity={intensity} phiEV={metal.phi} metalName={metal.name}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"flex flex-wrap gap-1.5\">\n            {METALS.map((m, i) => (\n              <button key={m.name} onClick={() => setMetalIdx(i)}\n                className={`rounded-full border px-2.5 py-1 text-[11px] font-medium transition ${\n                  metalIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{m.name}</button>\n            ))}\n          </div>\n          <Slider label=\"Frequency\" unit=\"×10¹⁴ Hz\" value={f14} min={2} max={14} step={0.1} set={setF14} color=\"#6366f1\" />\n          <Slider label=\"Intensity\" unit=\"\" value={intensity} min={1} max={10} step={1} set={setIntensity} color=\"#f59e0b\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function PhotoelectricEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <PhotoelectricEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/elasticity/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ElasticityCanvas, ElasticityMode } from '@/components/simulation/ElasticityCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { WIRE_MATERIALS } from '@/lib/physics/elasticity';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElasticityEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const mode = ((): ElasticityMode => (sp.get('mode') === 'wire' ? 'wire' : 'hooke'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [load, setLoad] = useState(() => num(sp, 'load', 8, 0, 30));\n  const [k, setK] = useState(() => num(sp, 'k', 200, 50, 500));\n  const [elasticLimitF, setElasticLimitF] = useState(() => num(sp, 'limit', 15, 5, 25));\n\n  const [matIdx, setMatIdx] = useState(() => Math.round(num(sp, 'mat', 0, 0, WIRE_MATERIALS.length - 1)));\n  const [wireLength, setWireLength] = useState(() => num(sp, 'L', 2, 0.5, 5));\n  const [wireDiamMm, setWireDiamMm] = useState(() => num(sp, 'd', 0.5, 0.1, 2));\n  const [wireLoad, setWireLoad] = useState(() => num(sp, 'F', 60, 5, 200));\n  const material = WIRE_MATERIALS[matIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [unloadKey, setUnloadKey] = useState(0);\n  const [settled, setSettled] = useState(false);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setSettled(false);\n  }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, load, k, elasticLimitF, matIdx, wireLength, wireDiamMm, wireLoad, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ElasticityCanvas key={resetKey} mode={mode}\n        load={mode === 'hooke' ? load : wireLoad} k={k} elasticLimitF={elasticLimitF}\n        wireLength={wireLength} wireDiamMm={wireDiamMm} youngE={material.E} materialName={material.name}\n        breakingStressMPa={material.breakingStressMPa}\n        isRunning={isRunning} isPaused={isPaused} unloadKey={unloadKey}\n        onSettled={() => setSettled(true)}\n        width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2, 1.6) : 2))} /></div>\n      <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n        {mode === 'hooke' && settled && (\n          <button onClick={() => { setUnloadKey(k => k + 1); setSettled(false); }}\n            className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-50\">\n            Remove load\n          </button>\n        )}\n      </div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {mode === 'hooke' ? <>\n            <Slider label=\"Load\" unit=\"N\" value={load} min={0} max={30} step={0.5} set={setLoad} color=\"#6366f1\" />\n            <Slider label=\"Spring constant\" unit=\"N/m\" value={k} min={50} max={500} step={10} set={setK} color=\"#f59e0b\" />\n            <Slider label=\"Elastic limit\" unit=\"N\" value={elasticLimitF} min={5} max={25} step={1} set={setElasticLimitF} color=\"#ef4444\" />\n          </> : <>\n            <div className=\"flex flex-wrap gap-1.5\">\n              {WIRE_MATERIALS.map((m, i) => (\n                <button key={m.name} onClick={() => setMatIdx(i)}\n                  className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                    matIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m.name}</button>\n              ))}\n            </div>\n            <Slider label=\"Load\" unit=\"N\" value={wireLoad} min={5} max={200} step={5} set={setWireLoad} color=\"#6366f1\" />\n            <Slider label=\"Length\" unit=\"m\" value={wireLength} min={0.5} max={5} step={0.1} set={setWireLength} color=\"#10b981\" />\n            <Slider label=\"Diameter\" unit=\"mm\" value={wireDiamMm} min={0.1} max={2} step={0.05} set={setWireDiamMm} color=\"#8b5cf6\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElasticityEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElasticityEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/electrostatics-charging/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ChargingMethodsCanvas, ChargingMethod } from '@/components/simulation/ChargingMethodsCanvas';\nimport { ElectroscopeCanvas, ElectroscopeMode } from '@/components/simulation/ElectroscopeCanvas';\nimport { ElectrophorusCanvas } from '@/components/simulation/ElectrophorusCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'production' | 'electroscope' | 'electrophorus';\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElectrostaticsChargingEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'electroscope' || t === 'electrophorus' ? t : 'production';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [method, setMethod] = useState<ChargingMethod>(() => {\n    const m = sp.get('method');\n    return m === 'conduction' || m === 'induction' ? m : 'friction';\n  });\n  const [electroscopeMode, setElectroscopeMode] = useState<ElectroscopeMode>(() => (sp.get('mode') === 'testing' ? 'testing' : 'charging'));\n  const [rodSign, setRodSign] = useState<1 | -1>(() => (sp.get('rod') === '-1' ? -1 : 1));\n  const [electroscopeSign, setElectroscopeSign] = useState<1 | -1>(() => (sp.get('es') === '1' ? 1 : -1));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [electrophorusCycle, setElectrophorusCycle] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setElectrophorusCycle(0); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, method, electroscopeMode, rodSign, electroscopeSign, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\">{topic === 'production' && (\n        <ChargingMethodsCanvas key={resetKey} method={method} rodSign={rodSign} isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'electroscope' && (\n        <ElectroscopeCanvas key={resetKey} mode={electroscopeMode} rodSign={rodSign} electroscopeSign={electroscopeSign}\n          isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'electrophorus' && (\n        <ElectrophorusCanvas key={resetKey} isRunning={isRunning} isPaused={isPaused}\n          cycleCount={electrophorusCycle} onCycleComplete={() => setElectrophorusCycle(c => c + 1)} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} />\n      )}</div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'production' && (\n            <div className=\"flex flex-col gap-2\">\n              {(['friction', 'conduction', 'induction'] as const).map(m => (\n                <button key={m} onClick={() => setMethod(m)}\n                  className={`rounded-lg border px-3 py-2 text-xs font-medium capitalize text-left transition ${\n                    method === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m}</button>\n              ))}\n              {method !== 'friction' && (\n                <div className=\"flex gap-2 pt-1\">\n                  {([1, -1] as const).map(sgn => (\n                    <button key={sgn} onClick={() => setRodSign(sgn)}\n                      className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                        rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>Rod: {sgn > 0 ? '+' : '−'}</button>\n                  ))}\n                </div>\n              )}\n            </div>\n          )}\n          {topic === 'electroscope' && <>\n            <div className=\"flex gap-2\">\n              {(['charging', 'testing'] as const).map(m => (\n                <button key={m} onClick={() => setElectroscopeMode(m)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    electroscopeMode === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m}</button>\n              ))}\n            </div>\n            {electroscopeMode === 'testing' && (\n              <div className=\"flex gap-2\">\n                {([1, -1] as const).map(sgn => (\n                  <button key={sgn} onClick={() => setElectroscopeSign(sgn)}\n                    className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                      electroscopeSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                    }`}>Electroscope: {sgn > 0 ? '+' : '−'}</button>\n                ))}\n              </div>\n            )}\n            <div className=\"flex gap-2\">\n              {([1, -1] as const).map(sgn => (\n                <button key={sgn} onClick={() => setRodSign(sgn)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>Rod: {sgn > 0 ? '+' : '−'}</button>\n              ))}\n            </div>\n          </>}\n          {topic === 'electrophorus' && (\n            <p className=\"text-xs text-gray-500\">Press Run to lower the disc, earth it, and lift it away.</p>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElectrostaticsChargingEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElectrostaticsChargingEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/atomic-models/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicParams, AtomicModel } from '@/lib/physics/atomicModels';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key); return v !== null ? v === '1' : fallback;\n}\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction AtomicModelsEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [model, setModel] = useState<AtomicModel>(() => str(sp, 'model', 'thomson', ['thomson', 'rutherford', 'bohr', 'quantum']));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [zoom, setZoom] = useState(() => num(sp, 'zoom', 1, 0.3, 3));\n  const [showOrbits, setShowOrbits] = useState(() => bool(sp, 'orbits', true));\n  const [showNucleus, setShowNucleus] = useState(() => bool(sp, 'nucleus', true));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'electrons', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showSpectrum, setShowSpectrum] = useState(() => bool(sp, 'spectrum', true));\n  const [showLabels, setShowLabels] = useState(() => bool(sp, 'labels', true));\n  const [showSpin, setShowSpin] = useState(() => bool(sp, 'spin', false));\n  const [showFineStructure, setShowFineStructure] = useState(() => bool(sp, 'fs', false));\n  const [showZeeman, setShowZeeman] = useState(() => bool(sp, 'zeeman', false));\n  const [magneticField, setMagneticField] = useState(() => num(sp, 'B', 0, 0, 5));\n  const [nQuantum, setNQuantum] = useState(() => num(sp, 'n', 1, 1, 4));\n  const [lQuantum, setLQuantum] = useState(() => num(sp, 'l', 0, 0, 3));\n  const [mQuantum, setMQuantum] = useState(() => num(sp, 'm', 0, -3, 3));\n  const [protonCount, setProtonCount] = useState(() => num(sp, 'Z', 1, 1, 92));\n  const [alphaEnergy, setAlphaEnergy] = useState(() => num(sp, 'alphaE', 5, 1, 10));\n\n  const params: AtomicParams = {\n    model, speed, zoom, showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure, showZeeman,\n    magneticField, nQuantum, lQuantum, mQuantum, protonCount, neutronCount: 0,\n    electronCount: 1, alphaEnergy,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => {\n          const labels: Record<AtomicModel, string> = { thomson: 'Thomson', rutherford: 'Rutherford', bohr: 'Bohr', quantum: 'Quantum' };\n          return (\n            <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n              className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n              {labels[m]}\n            </button>\n          );\n        })}\n      </div>\n\n      <div data-stage-role=\"canvas\"><AtomicModelsCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" />\n          <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" />\n          {model === 'rutherford' && <Slider label=\"α energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" />}\n          {model === 'bohr' && showZeeman && <Slider label=\"B field\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" />}\n          {model === 'quantum' && (\n            <>\n              <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" />\n              <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" />\n              <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" />\n            </>\n          )}\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" />Nucleus</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" />Probability</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" />Labels</label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">Powered by <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">A-Factor STEM Studio</a></p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function AtomicModelsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <AtomicModelsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/coupled-oscillators/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { CoupledOscillatorsCanvas } from '@/components/simulation/CoupledOscillatorsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { OscillatorParams } from '@/lib/physics/coupledOscillators';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={e => set(Number(e.target.value))}\n        className=\"w-full h-6 py-2 cursor-pointer\"\n        style={{ accentColor: color }}\n      />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction CoupledOscillatorsEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [m1, setM1] = useState(() => num(sp, 'm1', 1, 0.1, 5));\n  const [m2, setM2] = useState(() => num(sp, 'm2', 1, 0.1, 5));\n  const [k1, setK1] = useState(() => num(sp, 'k1', 1, 0.1, 5));\n  const [k2, setK2] = useState(() => num(sp, 'k2', 0.2, 0, 5));\n  const [k3, setK3] = useState(() => num(sp, 'k3', 1, 0.1, 5));\n  const [x1, setX1] = useState(() => num(sp, 'x1', 0.1, -0.3, 0.3));\n  const [x2, setX2] = useState(() => num(sp, 'x2', 0.1, -0.3, 0.3));\n  const [v1, setV1] = useState(() => num(sp, 'v1', 0, -2, 2));\n  const [v2, setV2] = useState(() => num(sp, 'v2', 0, -2, 2));\n  const [damping1, setDamping1] = useState(() => num(sp, 'd1', 0, 0, 1));\n  const [damping2, setDamping2] = useState(() => num(sp, 'd2', 0, 0, 1));\n  const [trailLength, setTrailLength] = useState(() => Math.round(num(sp, 'trail', 300, 0, 800)));\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n\n  const params: OscillatorParams = { m1, m2, k1, k2, k3, damping1, damping2 };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><CoupledOscillatorsCanvas\n        key={resetKey}\n        x1Init={x1}\n        v1Init={v1}\n        x2Init={x2}\n        v2Init={v2}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        showTrail={showTrail}\n        showEnergy={showEnergy}\n        trailLength={trailLength}\n        width={Math.max(160, embedSize.width - 24)}\n        height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(1.6, 1.6) : 1.6))}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">