 data-stage-role=\"canvas\">{topic === 'static-dynamic' && (\n        <StaticDynamicCanvas key={resetKey} scenario={scenario} f1={sdF1} f2={sdF2} mass={sdMass}\n          isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.6666666666666665, 1.6) : 2.6666666666666665))} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'concurrent' && (\n        <ConcurrentForcesCanvas key={resetKey} magA={magA} angleA={angleA} magB={magB} angleB={angleB}\n          isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.2857142857142856, 1.6) : 2.2857142857142856))} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'parallel' && (\n        <ParallelForcesCanvas key={resetKey} weights={weights}\n          isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.4615384615384617, 1.6) : 2.4615384615384617))} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'floating' && (\n        <FloatingBodyCanvas key={resetKey} objDensity={objDensity} liquidDensity={liquid.density}\n          liquidName={liquid.name} blockHeight={blockHeight}\n          isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.2857142857142856, 1.6) : 2.2857142857142856))} />\n      )}</div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'static-dynamic' && <>\n            <div className=\"flex gap-2\">\n              {(['static', 'dynamic'] as const).map(sc => (\n                <button key={sc} onClick={() => setScenario(sc)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    scenario === sc ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{sc}</button>\n              ))}\n            </div>\n            <Slider label=\"Force F1\" unit=\"N\" value={sdF1} min={0} max={30} step={0.5} set={setSdF1} color=\"#10b981\" />\n            <Slider label=\"Force F2\" unit=\"N\" value={sdF2} min={0} max={30} step={0.5} set={setSdF2} color=\"#ef4444\" />\n            <Slider label=\"Mass\" unit=\"kg\" value={sdMass} min={1} max={20} step={0.5} set={setSdMass} color=\"#6366f1\" />\n          </>}\n          {topic === 'concurrent' && <>\n            <Slider label=\"Force A\" unit=\"N\" value={magA} min={1} max={20} step={0.5} set={setMagA} color=\"#6366f1\" />\n            <Slider label=\"Angle A\" unit=\"°\" value={angleA} min={0} max={359} step={1} set={setAngleA} color=\"#818cf8\" />\n            <Slider label=\"Force B\" unit=\"N\" value={magB} min={1} max={20} step={0.5} set={setMagB} color=\"#10b981\" />\n            <Slider label=\"Angle B\" unit=\"°\" value={angleB} min={0} max={359} step={1} set={setAngleB} color=\"#34d399\" />\n          </>}\n          {topic === 'parallel' && <>\n            <Slider label=\"Weight 1\" unit=\"N\" value={w1Force} min={0} max={50} step={1} set={setW1Force} color=\"#6366f1\" />\n            <Slider label=\"Weight 1 ruler mark\" unit=\"cm\" value={Math.round((w1Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW1Pos(v / 100 - 0.5)} color=\"#6366f1\" />\n            <Slider label=\"Weight 2\" unit=\"N\" value={w2Force} min={0} max={50} step={1} set={setW2Force} color=\"#10b981\" />\n            <Slider label=\"Weight 2 ruler mark\" unit=\"cm\" value={Math.round((w2Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW2Pos(v / 100 - 0.5)} color=\"#6366f1\" />\n          </>}\n          {topic === 'floating' && <>\n            <div className=\"flex flex-wrap gap-1.5\">\n              {LIQUIDS.map((l, i) => (\n                <button key={l.name} onClick={() => setLiqIdx(i)}\n                  className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                    liqIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{l.name}</button>\n              ))}\n            </div>\n            <Slider label=\"Object density\" unit=\"kg/m³\" value={objDensity} min={100} max={12000} step={50} set={setObjDensity} color=\"#a78bfa\" />\n            <Slider label=\"Block height\" unit=\"m\" value={blockHeight} min={0.05} max={0.4} step={0.01} set={setBlockHeight} color=\"#f59e0b\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function EquilibriumEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <EquilibriumEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/xrays/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { XrayCanvas } from '@/components/simulation/XrayCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction XraysEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [kV, setKV] = useState(() => num(sp, 'kV', 35, 5, 100));\n  const [current, setCurrent] = useState(() => num(sp, 'i', 5, 1, 10));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [kV, current, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><XrayCanvas kV={kV} current={current} isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Tube voltage\" unit=\"kV\" value={kV} min={5} max={100} step={1} set={setKV} color=\"#6366f1\" />\n          <Slider label=\"Filament current\" unit=\"\" value={current} min={1} max={10} step={1} set={setCurrent} color=\"#f59e0b\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function XraysEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <XraysEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/band-theory/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { BandTheoryCanvas } from '@/components/simulation/BandTheoryCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { BandTheoryParams, DopingType, MATERIALS } from '@/lib/physics/bandTheory';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key);\n  return v !== null ? v === '1' : fallback;\n}\n\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"font-normal text-gray-400\">{unit}</span>\n        </span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction BandTheoryEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [material, setMaterial] = useState(() => str(sp, 'mat', 'silicon', Object.keys(MATERIALS)));\n  const [temperature, setTemperature] = useState(() => num(sp, 'T', 300, 0, 1000));\n  const [dopingType, setDopingType] = useState<DopingType>(() => str(sp, 'dopant', 'intrinsic', ['intrinsic', 'n-type', 'p-type'] as DopingType[]));\n  const [dopingConcentration, setDopingConcentration] = useState(() => num(sp, 'conc', 10, 10, 20));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'e', true));\n  const [showHoles, setShowHoles] = useState(() => bool(sp, 'h', true));\n  const [showFermiLevel, setShowFermiLevel] = useState(() => bool(sp, 'ef', true));\n  const [showBandGap, setShowBandGap] = useState(() => bool(sp, 'eg', true));\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 540, 1600, 420);\n  const params: BandTheoryParams = {\n    material, temperature, dopingType, dopingConcentration,\n    speed, zoom: 1, showElectrons, showHoles, showFermiLevel,\n    showBandGap, showThermalEnergy: false, showDOS: true, animateCarriers: true,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey((k) => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {Object.entries(MATERIALS).map(([key, m]) => (\n          <button key={key} onClick={() => { setMaterial(key); setIsRunning(false); setResetKey((k) => k + 1); }}\n            className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${material === key ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n            {m.symbol}\n          </button>\n        ))}\n      </div>\n\n      <div data-stage-role=\"canvas\" ref={canvasBoxRef}><BandTheoryCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} /></div>\n      <div data-stage-role=\"extra\"><p className=\"text-xs leading-6 text-gray-700\">Filled dots are electrons; hollow markers are unoccupied states. The row illustrates an electron filling a hole: the vacancy shifts the other way. Counts are amplified; low-temperature freeze-out and degenerate doping are outside this teaching approximation.</p></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused((p) => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Temperature\" unit=\"K\" value={temperature} min={0} max={1000} step={10} set={setTemperature} color=\"#f43f5e\" />\n          <Slider label=\"Doping\" unit=\"log₁₀(cm⁻³)\" value={dopingConcentration} min={10} max={20} step={0.5} set={setDopingConcentration} color=\"#8b5cf6\" />\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showElectrons} onChange={(e) => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showHoles} onChange={(e) => setShowHoles(e.target.checked)} className=\"rounded\" />Holes\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showFermiLevel} onChange={(e) => setShowFermiLevel(e.target.checked)} className=\"rounded\" />Fermi level\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showBandGap} onChange={(e) => setShowBandGap(e.target.checked)} className=\"rounded\" />Band gap\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function BandTheoryEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <BandTheoryEmbedInner />\n    </Suspense>\n  );\n}", "src/app/embed/optics/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { OpticsCanvas, OpticsMode } from '@/components/simulation/OpticsCanvas';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction OpticsEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const mode = ((): OpticsMode => (sp.get('mode') === 'lens' ? 'lens' : 'snell'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [n1, setN1] = useState(() => num(sp, 'n1', 1.0, 1, 2.5));\n  const [n2, setN2] = useState(() => num(sp, 'n2', 1.5, 1, 2.5));\n  const [theta1, setTheta1] = useState(() => num(sp, 'theta1', 35, 0, 89));\n  const [focal, setFocal] = useState(() => num(sp, 'focal', 15, 5, 40));\n  const [objectDist, setObjectDist] = useState(() => num(sp, 'u', 40, 5, 90));\n  const [converging, setConverging] = useState(() => sp.get('conv') !== '0');\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><OpticsCanvas mode={mode} n1={n1} n2={n2} theta1={theta1}\n        focal={focal} objectDist={objectDist} converging={converging}\n        width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.0625, 1.6) : 2.0625))} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            {mode === 'snell' && <>\n              <Slider label=\"Angle of incidence θ₁\" unit=\"°\" value={theta1} min={0} max={89} step={1} set={setTheta1} color=\"#6366f1\" />\n              <Slider label=\"n₁ (top)\" unit=\"\" value={n1} min={1} max={2.5} step={0.01} set={setN1} color=\"#f59e0b\" />\n              <Slider label=\"n₂ (bottom)\" unit=\"\" value={n2} min={1} max={2.5} step={0.01} set={setN2} color=\"#10b981\" />\n            </>}\n            {mode !== 'snell' && <>\n              <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n              <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\" />\n              <div className=\"space-y-1\">\n                <span className=\"text-xs text-gray-500\">Type</span>\n                <div className=\"flex gap-2\">\n                  {([true, false] as const).map(c => (\n                    <button key={String(c)} onClick={() => setConverging(c)}\n                      className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium transition ${\n                        converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>\n                      {c ? 'Converging' : 'Diverging'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </>}\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function OpticsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <OpticsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/double-pendulum/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DoublePendulumCanvas } from '@/components/simulation/DoublePendulumCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PendulumParams } from '@/lib/physics/doublePendulum';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DoublePendulumEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [m1, setM1] = useState(() => num(sp, 'm1', 1, 0.1, 3));\n  const [m2, setM2] = useState(() => num(sp, 'm2', 1, 0.1, 3));\n  const [L1, setL1] = useState(() => num(sp, 'L1', 1, 0.3, 2));\n  const [L2, setL2] = useState(() => num(sp, 'L2', 1, 0.3, 2));\n  const [theta1Deg, setTheta1Deg] = useState(() => num(sp, 't1', 90, -180, 180));\n  const [theta2Deg, setTheta2Deg] = useState(() => num(sp, 't2', 90, -180, 180));\n  const [omega1, setOmega1] = useState(() => num(sp, 'w1', 0, -5, 5));\n  const [omega2, setOmega2] = useState(() => num(sp, 'w2', 0, -5, 5));\n  const [damping, setDamping] = useState(() => num(sp, 'damping', 0, 0, 0.5));\n  const [trailLength, setTrailLength] = useState(() => Math.round(num(sp, 'trail', 300, 0, 800)));\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n\n  const params: PendulumParams = { m1, m2, L1, L2, g: 9.81, damping };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DoublePendulumCanvas\n        key={resetKey}\n        theta1Deg={theta1Deg}\n        omega1Init={omega1}\n        theta2Deg={theta2Deg}\n        omega2Init={omega2}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        showTrail={showTrail}\n        showEnergy={showEnergy}\n        trailLength={trailLength}\n        width={Math.max(160, embedSize.width - 24)}\n        height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(1.6, 1.6) : 1.6))}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Mass m₁\" unit=\"kg\" value={m1} min={0.1} max={3} step={0.1} set={setM1} color=\"#6366f1\" />\n          <Slider label=\"Mass m₂\" unit=\"kg\" value={m2} min={0.1} max={3} step={0.1} set={setM2} color=\"#f59e0b\" />\n          <Slider label=\"Length L₁\" unit=\"m\" value={L1} min={0.3} max={2} step={0.1} set={setL1} color=\"#818cf8\" />\n          <Slider label=\"Length L₂\" unit=\"m\" value={L2} min={0.3} max={2} step={0.1} set={setL2} color=\"#fbbf24\" />\n          <Slider label=\"Angle θ₁\" unit=\"°\" value={theta1Deg} min={-180} max={180} step={1} set={setTheta1Deg} color=\"#a78bfa\" />\n          <Slider label=\"Angle θ₂\" unit=\"°\" value={theta2Deg} min={-180} max={180} step={1} set={setTheta2Deg} color=\"#fcd34d\" />\n          <Slider label=\"Damping\" unit=\"\" value={damping} min={0} max={0.5} step={0.01} set={setDamping} color=\"#ef4444\" />\n          <Slider label=\"Trail\" unit=\"frames\" value={trailLength} min={0} max={800} step={10} set={setTrailLength} color=\"#f43f5e\" />\n          <div className=\"flex gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showTrail} onChange={e => setShowTrail(e.target.checked)} className=\"rounded\" />\n              Show trail\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergy} onChange={e => setShowEnergy(e.target.checked)} className=\"rounded\" />\n              Show energy\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DoublePendulumEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DoublePendulumEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/heat/page.tsx": "'use client';\nimport { useRef as useEmbedRef } from 'react';\nimport { useResponsiveCanvasSize as useEmbedSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { HeatTransferCanvas, HeatMode } from '@/components/simulation/HeatTransferCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { MATERIALS } from '@/lib/physics/heat';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction HeatEmbedInner() {\n  const embedBoxRef = useEmbedRef<HTMLDivElement>(null);\n  const embedSize = useEmbedSize(embedBoxRef, 640, 360, 1100);\n\n  const sp = useSearchParams();\n  const mode = ((): HeatMode => {\n    const m = sp.get('mode');\n    return m === 'convection' || m === 'radiation' ? m : 'conduction';\n  })();\n  const showControls = sp.get('controls') !== '0';\n  const [hotTemp, setHotTemp] = useState(() => num(sp, 'hot', 90, 30, 120));\n  const [coldTemp, setColdTemp] = useState(() => num(sp, 'cold', 20, 0, 40));\n  const [materialIdx, setMaterialIdx] = useState(() => {\n    const i = MATERIALS.findIndex(m => m.name === sp.get('material'));\n    return i >= 0 ? i : 0;\n  });\n  const material = MATERIALS[materialIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, hotTemp, coldTemp, materialIdx, reset]);\n\n  return (\n    <SimulationStage containerRef={embedBoxRef} className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><HeatTransferCanvas mode={mode} hotTemp={hotTemp} coldTemp={coldTemp} materialK={material.k}\n        isRunning={isRunning} isPaused={isPaused} width={Math.max(160, embedSize.width - 24)} height={Math.round((Math.max(160, embedSize.width - 24)) / (embedSize.width < 600 ? Math.min(2.1333333333333333, 1.6) : 2.1333333333333333))} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Hot temperature\" unit=\"°C\" value={hotTemp} min={30} max={120} step={5} set={setHotTemp} color=\"#ef4444\" />\n          <Slider label=\"Cold temperature\" unit=\"°C\" value={coldTemp} min={0} max={40} step={5} set={setColdTemp} color=\"#3b82f6\" />\n          {mode === 'conduction' && (\n            <div className=\"grid grid-cols-2 gap-1.5\">\n              {MATERIALS.map((m, i) => (\n                <button key={m.name} onClick={() => setMaterialIdx(i)}\n                  className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    materialIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m.name}</button>\n              ))}\n            </div>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function HeatEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <HeatEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/mosfet/page.tsx": "// src/app/embed/mosfet/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport { MosfetCanvas } from '@/components/simulation/MosfetCanvas';\nimport { MosfetParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/mosfet';\n\nexport default function MosfetEmbedPage() {\n  const [params, setParams] = useState<MosfetParams>(getPreset('cutoff'));\n  const [activePreset, setActivePreset] = useState('cutoff');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage className=\"af-embed-stage af-stage-dark mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n        <div data-stage-role=\"canvas\"><MosfetCanvas\n          params={params}\n          activeTab=\"schematic\"\n          isRunning={true}\n          isPaused={false}\n          showElectrons={true}\n        /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}\n", "src/components/simulation/SimulationStage.tsx": "'use client';\nimport { Children, isValidElement, useCallback, useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';\nimport './simulation-stage.css';\n\n/** Keeps the existing simulation mounted while expanding it with its controls. */\nexport function SimulationStage({ children, className = '', containerRef }: { children: ReactNode; className?: string; containerRef?: RefObject<HTMLDivElement | null> }) {\n  const [expanded, setExpanded] = useState(false);\n  const [controlsVisible, setControlsVisible] = useState(true);\n  const root = useRef<HTMLDivElement>(null);\n  const setRoot = useCallback((node: HTMLDivElement | null) => { root.current = node; if (containerRef) containerRef.current = node; }, [containerRef]);\n  const toggle = useRef<HTMLButtonElement>(null);\n  const previousFocus = useRef<HTMLElement | null>(null);\n  const orientationLocked = useRef(false);\n  const active = useRef(false);\n  const items = Children.toArray(children);\n  const role = (item: ReactNode) => isValidElement<{'data-stage-role'?: string}>(item) ? item.props['data-stage-role'] : undefined;\n  const hasContent = (item: ReactNode): boolean => {\n    if (!isValidElement<{children?: ReactNode}>(item)) return typeof item === 'string' ? item.trim().length > 0 : typeof item === 'number';\n    if (typeof item.type !== 'string') return true;\n    if (item.props.children === undefined) return ['input','canvas','iframe','img'].includes(item.type);\n    return Children.toArray(item.props.children).some(hasContent);\n  };\n  const parameters = items.filter(item => role(item) === 'parameters' && hasContent(item));\n  const scene = items.filter(item => role(item) !== 'parameters');\n  function unlock() { if (orientationLocked.current) { try { screen.orientation?.unlock(); } catch {} orientationLocked.current = false; } }\n  function close() {\n    active.current = false;\n    unlock();\n    if (document.fullscreenElement === root.current) void document.exitFullscreen().catch(() => {});\n    setExpanded(false);\n  }\n  function open() {\n    active.current = true;\n    previousFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;\n    setExpanded(true);\n    // Request landscape only after native fullscreen succeeds; physical rotation remains available.\n    try {\n      const request = root.current?.requestFullscreen?.();\n      if (request) void request.then(async () => {\n        if (!active.current) { if (document.fullscreenElement === root.current) void document.exitFullscreen().catch(() => {}); return; }\n        if (!window.matchMedia('(pointer: coarse)').matches) return;\n        const orientation = screen.orientation as ScreenOrientation & { lock?: (mode: string) => Promise<void> };\n        try { await orientation.lock?.('landscape'); orientationLocked.current = !!orientation.lock; if (!active.current) unlock(); } catch {}\n      }).catch(() => {});\n    } catch {}\n  }\n  useEffect(() => {\n    if (!expanded) return;\n    const old = document.body.style.overflow;\n    document.body.style.overflow = 'hidden';\n    toggle.current?.focus();\n    const escape = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };\n    const fullscreen = () => { if (!document.fullscreenElement) { active.current = false; unlock(); setExpanded(false); } };\n    document.addEventListener('keydown', escape);\n    document.addEventListener('fullscreenchange', fullscreen);\n    return () => {\n      active.current = false;\n      unlock();\n      document.body.style.overflow = old;\n      document.removeEventListener('keydown', escape);\n      document.removeEventListener('fullscreenchange', fullscreen);\n      previousFocus.current?.focus();\n    };\n  }, [expanded]);\n  useEffect(() => {\n    if (!expanded || !root.current) return;\n    const el = root.current;\n    const main = el.querySelector<HTMLElement>('.af-stage-main');\n    if (!main) return;\n    let frame = 0;\n    const resize = () => {\n      cancelAnimationFrame(frame);\n      frame = requestAnimationFrame(() => {\n        const playback = Array.from(main.querySelectorAll<HTMLElement>('[data-stage-role=\"playback\"]')).filter(p => p.getClientRects().length).reduce((sum, p) => sum + p.getBoundingClientRect().height, 0);\n        el.style.setProperty('--af-stage-canvas-height', `${Math.max(40, main.clientHeight - playback - 36)}px`);\n      });\n    };\n    const observer = new ResizeObserver(resize);\n    observer.observe(main);\n    main.querySelectorAll('[data-stage-role=\"playback\"]').forEach(p => observer.observe(p));\n    resize();\n    return () => { cancelAnimationFrame(frame); observer.disconnect(); el.style.removeProperty('--af-stage-canvas-height'); };\n  }, [expanded]);\n  return <div ref={setRoot} data-simulation-stage data-expanded={expanded} className={`af-simulation-stage ${className}`} data-has-parameters={parameters.length > 0} data-controls-visible={controlsVisible}\n    role={expanded ? 'dialog' : undefined} aria-modal={expanded || undefined} aria-label={expanded ? 'Classroom simulation view' : undefined}\n    onKeyDown={e => {\n      if (!expanded || e.key !== 'Tab') return;\n      const elements = Array.from(root.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href],iframe,[tabindex=\"0\"]') || []).filter(el => el.getClientRects().length);\n      const first = elements[0], last = elements[elements.length - 1];\n      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }\n      if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }\n    }}>\n    <div className=\"af-stage-toolbar\"><span>{expanded ? 'Classroom view' : 'Simulation'}{expanded && <small className=\"af-rotate-hint\"> · Rotate your phone for a wider view</small>}</span>\n      {expanded && parameters.length > 0 && <button type=\"button\" onClick={() => setControlsVisible(v => !v)} aria-expanded={controlsVisible}>{controlsVisible ? 'Hide parameters' : 'Show parameters'}</button>}\n      <button ref={toggle} type=\"button\" onClick={expanded ? close : open} aria-expanded={expanded}>{expanded ? 'Exit classroom view ✕' : '⛶ Expand simulation'}</button>\n    </div>\n    <div className=\"af-stage-body\">\n      <div className=\"af-stage-main\">{scene}</div>\n      {parameters.length > 0 && <aside className=\"af-stage-parameters\" aria-label=\"Simulation parameters\">{parameters}</aside>}\n    </div>\n  </div>;\n}\n", "src/components/simulation/BjtCanvas.tsx": "// src/components/simulation/BjtCanvas.tsx\n'use client';\n\nimport React, { useRef, useEffect, useCallback } from 'react';\nimport { computeBjtState, BjtParams, BjtState, REGION_COLORS } from '@/lib/physics/bjtTransistor';\n\ninterface BjtCanvasProps {\n  params: BjtParams;\n  width?: number;\n  height?: number;\n}\n\nexport default function BjtCanvas({ params, width = 900, height = 640 }: BjtCanvasProps) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const animRef = useRef<number>(0);\n  const timeRef = useRef<number>(0);\n  \n  const state = computeBjtState(params);\n  \n  const draw = useCallback((ctx: CanvasRenderingContext2D, t: number) => {\n    // These circuit diagrams use a fixed logical layout. Scale the whole\n    // drawing, including labels, rather than clipping its fixed coordinates.\n    const actualW = ctx.canvas.width, actualH = ctx.canvas.height;\n    const W = 900, H = 640;\n    const scale = Math.min(actualW / W, actualH / H);\n    ctx.setTransform(1, 0, 0, 1, 0, 0);\n    ctx.clearRect(0, 0, actualW, actualH);\n    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, actualW, actualH);\n    ctx.setTransform(scale, 0, 0, scale, (actualW - W * scale) / 2, (actualH - H * scale) / 2);\n    const { Vbe, Vce, temperature, material, beta, topology, Vcc, Rb, Rc, Re, Rload } = params;\n    const { region, Ib, Ic, Ie, Vb, Ve, Vc, Av, Ai, Ap, Zin, Zout, Pdiss, Ic_sat, Vce_cutoff } = state;\n    \n    ctx.clearRect(0, 0, W, H);\n    ctx.fillStyle = '#0f172a';\n    ctx.fillRect(0, 0, W, H);\n    \n    const margin = 45;\n    \n    drawCircuitSchematic(ctx, margin, 55, 420, 320, params, state, t);\n    drawTransistorCrossSection(ctx, W - margin - 280, 55, 280, 180, params, state, t);\n    drawOutputCharacteristics(ctx, W - margin - 280, 255, 280, 180, params, state);\n    drawCircuitAnalysis(ctx, margin, 395, 420, 140, params, state);\n    drawCurrentFlow(ctx, margin, 550, W - margin*2, 50, params, state, t);\n    \n    ctx.fillStyle = 'rgba(15, 23, 42, 0.92)';\n    ctx.fillRect(margin, H - 42, W - margin*2, 34);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(margin, H - 42, W - margin*2, 34);\n    \n    ctx.fillStyle = '#e2e8f0'; ctx.font = '11px monospace'; ctx.textAlign = 'left';\n    ctx.fillText(`Vbe=${Vbe.toFixed(2)}V  Vce=${Vce.toFixed(2)}V  Vb=${Vb.toFixed(2)}V  Ve=${Ve.toFixed(2)}V  Vc=${Vc.toFixed(2)}V`, margin + 10, H - 22);\n    ctx.fillStyle = region === 'active' ? '#4ade80' : region === 'saturation' ? '#f87171' : '#94a3b8';\n    ctx.fillText(region.toUpperCase(), W - margin - 80, H - 22);\n    \n    ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 15px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText(`${material} NPN BJT — ${topology.replace(/-/g, ' ').toUpperCase()} @ ${temperature}K`, W/2, 22);\n    \n  }, [params, state]);\n  \n  function drawCircuitSchematic(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, params: BjtParams, state: BjtState, t: number) {\n    const { topology, Vcc, Rb, Rc, Re, Rload } = params;\n    const { Ib, Ic, Ie } = state;\n    const cx = x + w/2;\n    const cy = y + h/2;\n    \n    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;\n    \n    if (topology === 'common-emitter') {\n      ctx.beginPath(); ctx.moveTo(x + 30, y + 20); ctx.lineTo(x + w - 30, y + 20); ctx.stroke();\n      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText(`+Vcc = ${Vcc}V`, x + 35, y + 16);\n      \n      ctx.beginPath(); ctx.moveTo(cx + 40, y + 20); ctx.lineTo(cx + 40, cy - 45); ctx.stroke();\n      drawResistor(ctx, cx + 40, cy - 45, 'vertical', Rc, 'Rc');\n      ctx.beginPath(); ctx.moveTo(cx + 40, cy - 25); ctx.lineTo(cx + 40, cy - 10); ctx.stroke();\n      \n      drawNpnSymbol(ctx, cx, cy, 50);\n      \n      ctx.beginPath(); ctx.moveTo(cx - 35, cy); ctx.lineTo(cx - 80, cy); ctx.stroke();\n      drawResistor(ctx, cx - 80, cy, 'horizontal', Rb, 'Rb');\n      ctx.beginPath(); ctx.moveTo(cx - 100, cy); ctx.lineTo(cx - 120, cy); ctx.stroke();\n      ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.arc(cx - 135, cy, 12, 0, Math.PI*2); ctx.stroke();\n      ctx.fillStyle = '#60a5fa'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n      ctx.fillText('~', cx - 135, cy + 3);\n      ctx.fillText('Vin', cx - 135, cy + 28);\n      \n      ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;\n      ctx.beginPath(); ctx.moveTo(cx - 135, cy + 12); ctx.lineTo(cx - 135, cy + 35); ctx.stroke();\n      drawGround(ctx, cx - 135, cy + 35);\n      \n      ctx.beginPath(); ctx.moveTo(cx, cy + 50); ctx.lineTo(cx, cy + 80); ctx.stroke();\n      if (Re > 0.1) {\n        drawResistor(ctx, cx, cy + 80, 'vertical', Re, 'Re');\n        ctx.beginPath(); ctx.moveTo(cx, cy + 100); ctx.lineTo(cx, cy + 115); ctx.stroke();\n      }\n      drawGround(ctx, cx, cy + 115);\n      \n      ctx.fillStyle = '#4ade80'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText('Vout', cx + 48, cy - 30);\n      \n      ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.moveTo(cx + 40, cy - 10); ctx.lineTo(cx + 100, cy - 10); ctx.stroke();\n      drawResistor(ctx, cx + 100, cy - 10, 'horizontal', Rload, 'Rload');\n      ctx.beginPath(); ctx.moveTo(cx + 120, cy - 10); ctx.lineTo(cx + 140, cy - 10); ctx.stroke();\n      drawGround(ctx, cx + 140, cy - 10);\n      \n      if (Ic > 0.01) {\n        ctx.fillStyle = '#fbbf24';\n        const progress = (t * Ic * 0.3) % 1;\n        const cy_flow = y + 20 + progress * (cy + 50 - y - 20);\n        ctx.beginPath(); ctx.arc(cx + 40, cy_flow, 3, 0, Math.PI*2); ctx.fill();\n      }\n      if (Ib > 0.1) {\n        ctx.fillStyle = '#f87171';\n        const progress = (t * Ib * 0.01) % 1;\n        const bx_flow = cx - 120 + progress * 85;\n        ctx.beginPath(); ctx.arc(bx_flow, cy, 2.5, 0, Math.PI*2); ctx.fill();\n      }\n      if (Ie > 0.01) {\n        ctx.fillStyle = '#60a5fa';\n        const progress = (t * Ie * 0.3) % 1;\n        const ey_flow = cy + 50 + progress * 65;\n        ctx.beginPath(); ctx.arc(cx, ey_flow, 3, 0, Math.PI*2); ctx.fill();\n      }\n      \n    } else if (topology === 'common-collector') {\n      ctx.beginPath(); ctx.moveTo(cx, y + 20); ctx.lineTo(cx, cy - 55); ctx.stroke();\n      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';\n      ctx.fillText(`+Vcc = ${Vcc}V`, cx, y + 16);\n      \n      drawNpnSymbol(ctx, cx, cy, 50);\n      \n      ctx.beginPath(); ctx.moveTo(cx - 35, cy); ctx.lineTo(cx - 80, cy); ctx.stroke();\n      drawResistor(ctx, cx - 80, cy, 'horizontal', Rb, 'Rb');\n      ctx.beginPath(); ctx.moveTo(cx - 100, cy); ctx.lineTo(cx - 120, cy); ctx.stroke();\n      ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.arc(cx - 135, cy, 12, 0, Math.PI*2); ctx.stroke();\n      ctx.fillStyle = '#60a5fa'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n      ctx.fillText('~', cx - 135, cy + 3);\n      ctx.fillText('Vin', cx - 135, cy + 28);\n      \n      ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;\n      ctx.beginPath(); ctx.moveTo(cx - 135, cy + 12); ctx.lineTo(cx - 135, cy + 35); ctx.stroke();\n      drawGround(ctx, cx - 135, cy + 35);\n      \n      ctx.beginPath(); ctx.moveTo(cx, cy + 50); ctx.lineTo(cx, cy + 75); ctx.stroke();\n      drawResistor(ctx, cx, cy + 75, 'vertical', Re, 'Re');\n      ctx.beginPath(); ctx.moveTo(cx, cy + 95); ctx.lineTo(cx, cy + 110); ctx.stroke();\n      \n      ctx.beginPath(); ctx.moveTo(cx + 30, cy + 85); ctx.lineTo(cx + 70, cy + 85); ctx.stroke();\n      drawResistor(ctx, cx + 70, cy + 85, 'horizontal', Rload, 'Rload');\n      ctx.beginPath(); ctx.moveTo(cx + 90, cy + 85); ctx.lineTo(cx + 110, cy + 85); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(cx + 110, cy + 85); ctx.lineTo(cx + 110, cy + 110); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(cx, cy + 110); ctx.lineTo(cx + 110, cy + 110); ctx.stroke();\n      drawGround(ctx, cx + 55, cy + 110);\n      \n      ctx.fillStyle = '#4ade80'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText('Vout', cx + 5, cy + 80);\n      \n      if (Ie > 0.01) {\n        ctx.fillStyle = '#fbbf24';\n        const progress = (t * Ie * 0.3) % 1;\n        const ey = cy + 50 + progress * 60;\n        ctx.beginPath(); ctx.arc(cx, ey, 3, 0, Math.PI*2); ctx.fill();\n      }\n      \n    } else if (topology === 'common-base') {\n      ctx.beginPath(); ctx.moveTo(cx + 30, y + 20); ctx.lineTo(cx + 30, cy - 55); ctx.stroke();\n      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText(`+Vcc = ${Vcc}V`, x + 35, y + 16);\n      drawResistor(ctx, cx + 30, cy - 55, 'vertical', Rc, 'Rc');\n      ctx.beginPath(); ctx.moveTo(cx + 30, cy - 35); ctx.lineTo(cx + 30, cy - 10); ctx.stroke();\n      \n      drawNpnSymbol(ctx, cx, cy, 50);\n      \n      ctx.beginPath(); ctx.moveTo(cx - 35, cy); ctx.lineTo(cx - 80, cy); ctx.stroke();\n      drawGround(ctx, cx - 80, cy);\n      \n      ctx.beginPath(); ctx.moveTo(cx, cy + 50); ctx.lineTo(cx, cy + 80); ctx.stroke();\n      drawResistor(ctx, cx, cy + 80, 'vertical', Re, 'Re');\n      ctx.beginPath(); ctx.moveTo(cx, cy + 100); ctx.lineTo(cx, cy + 115); ctx.stroke();\n      ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.arc(cx, cy + 130, 12, 0, Math.PI*2); ctx.stroke();\n      ctx.fillStyle = '#60a5fa'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n      ctx.fillText('~', cx, cy + 133);\n      ctx.fillText('Vin', cx, cy + 155);\n      drawGround(ctx, cx, cy + 155);\n      \n      ctx.fillStyle = '#4ade80'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText('Vout', cx + 38, cy - 30);\n      \n      if (Ic > 0.01) {\n        ctx.fillStyle = '#fbbf24';\n        const progress = (t * Ic * 0.3) % 1;\n        const dy = y + 20 + progress * (cy - 30 - y - 20);\n        ctx.beginPath(); ctx.arc(cx + 30, dy, 3, 0, Math.PI*2); ctx.fill();\n      }\n    }\n  }\n  \n  function drawNpnSymbol(ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number) {\n    ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 2.5;\n    ctx.beginPath(); ctx.moveTo(cx - 25, cy - 30); ctx.lineTo(cx - 25, cy + 30); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(cx - 25, cy - 20); ctx.lineTo(cx + 15, cy - 40); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(cx - 25, cy + 20); ctx.lineTo(cx + 15, cy + 40); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(cx + 8, cy + 32); ctx.lineTo(cx + 15, cy + 40); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(cx + 15, cy + 40); ctx.lineTo(cx + 5, cy + 38); ctx.stroke();\n    ctx.strokeStyle = '#475569'; ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.arc(cx, cy, size/2 + 5, 0, Math.PI*2); ctx.stroke();\n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('C', cx + 22, cy - 42);\n    ctx.fillText('B', cx - 38, cy);\n    ctx.fillText('E', cx + 22, cy + 48);\n  }\n  \n  function drawResistor(ctx: CanvasRenderingContext2D, x: number, y: number, orientation: 'horizontal' | 'vertical', value: number, label: string) {\n    ctx.strokeStyle = '#f87171'; ctx.lineWidth = 2;\n    const seg = 8;\n    if (orientation === 'vertical') {\n      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 5); ctx.stroke();\n      ctx.beginPath();\n      ctx.moveTo(x, y + 5);\n      for (let i = 0; i < 4; i++) {\n        ctx.lineTo(x - 5, y + 10 + i*seg);\n        ctx.lineTo(x + 5, y + 14 + i*seg);\n      }\n      ctx.lineTo(x, y + 42);\n      ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(x, y + 42); ctx.lineTo(x, y + 47); ctx.stroke();\n      ctx.fillStyle = '#f87171'; ctx.font = '9px sans-serif'; ctx.textAlign = 'left';\n      ctx.fillText(`${label}=${value}k`, x + 8, y + 28);\n    } else {\n      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 5, y); ctx.stroke();\n      ctx.beginPath();\n      ctx.moveTo(x + 5, y);\n      for (let i = 0; i < 4; i++) {\n        ctx.lineTo(x + 10 + i*seg, y - 5);\n        ctx.lineTo(x + 14 + i*seg, y + 5);\n      }\n      ctx.lineTo(x + 42, y);\n      ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(x + 42, y); ctx.lineTo(x + 47, y); ctx.stroke();\n      ctx.fillStyle = '#f87171'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';\n      ctx.fillText(`${label}=${value}k`, x + 26, y - 10);\n    }\n  }\n  \n  function drawGround(ctx: CanvasRenderingContext2D, x: number, y: number) {\n    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 10); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(x - 10, y + 10); ctx.lineTo(x + 10, y + 10); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(x - 7, y + 14); ctx.lineTo(x + 7, y + 14); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(x - 4, y + 18); ctx.lineTo(x + 4, y + 18); ctx.stroke();\n  }\n  \n  function drawTransistorCrossSection(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, params: BjtParams, state: BjtState, t: number) {\n    const { Vbe, Vce, beta } = params;\n    const { region, Ib, Ic, Ie } = state;\n    const cx = x + w/2;\n    const devW = w - 20;\n    const devH = h - 40;\n    const devX = x + 10;\n    const devY = y + 20;\n    \n    ctx.fillStyle = '#1e293b';\n    ctx.fillRect(devX, devY, devW, devH);\n    \n    ctx.fillStyle = '#1d4ed8';\n    ctx.fillRect(devX + 10, devY + 10, 50, devH - 20);\n    \n    ctx.fillStyle = '#be185d';\n    ctx.fillRect(devX + 60, devY + 25, 30, devH - 50);\n    \n    ctx.fillStyle = '#1d4ed8';\n    ctx.fillRect(devX + 90, devY + 10, 60, devH - 20);\n    \n    ctx.strokeStyle = '#94a3b8'; ctx.setLineDash([3, 3]); ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(devX + 60, devY + 10); ctx.lineTo(devX + 60, devY + devH - 10); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(devX + 90, devY + 10); ctx.lineTo(devX + 90, devY + devH - 10); ctx.stroke();\n    ctx.setLineDash([]);\n    \n    ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('E', devX + 35, devY + devH/2);\n    ctx.fillText('B', devX + 75, devY + devH/2);\n    ctx.fillText('C', devX + 120, devY + devH/2);\n    \n    if (region !== 'cutoff') {\n      const elecCount = Math.min(20, Math.floor(Ic * 3));\n      for (let i = 0; i < elecCount; i++) {\n        const progress = ((t * 0.8 + i * 0.12) % 1);\n        let ex, ey;\n        if (progress < 0.3) {\n          ex = devX + 15 + progress/0.3 * 45;\n          ey = devY + 15 + (i % 4) * (devH - 30)/4;\n        } else if (progress < 0.6) {\n          ex = devX + 60 + (progress - 0.3)/0.3 * 30;\n          ey = devY + 15 + (i % 4) * (devH - 30)/4 + Math.sin((progress - 0.3)/0.3 * Math.PI) * 5;\n        } else {\n          ex = devX + 90 + (progress - 0.6)/0.4 * 55;\n          ey = devY + 15 + (i % 4) * (devH - 30)/4;\n        }\n        ctx.fillStyle = '#60a5fa';\n        ctx.beginPath(); ctx.arc(ex, ey, 2.5, 0, Math.PI*2); ctx.fill();\n      }\n      \n      if (Ib > 0.1) {\n        for (let i = 0; i < 3; i++) {\n          const flicker = Math.sin(t * 4 + i * 2) > 0.6;\n          if (flicker) {\n            ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1.2;\n            const rx = devX + 65 + i * 8;\n            const ry = devY + 30 + (i % 2) * 20;\n            ctx.beginPath();\n            ctx.moveTo(rx - 3, ry - 3); ctx.lineTo(rx + 3, ry + 3);\n            ctx.moveTo(rx + 3, ry - 3); ctx.lineTo(rx - 3, ry + 3);\n            ctx.stroke();\n          }\n        }\n      }\n    }\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('Device Cross-Section', cx, y + 12);\n  }\n  \n  function drawOutputCharacteristics(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, params: BjtParams, state: BjtState) {\n    const { Vcc, Rc, Re, beta, Vce } = params;\n    const { Ic, Ic_sat, Vce_cutoff } = state;\n    const Ib_values = [10, 20, 40, 80, 160];\n    \n    ctx.fillStyle = 'rgba(15, 23, 42, 0.95)';\n    ctx.fillRect(x, y, w, h);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(x, y, w, h);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('Output Characteristics (Ic vs Vce)', x + w/2, y + 14);\n    \n    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(x + 28, y + h - 22);\n    ctx.lineTo(x + w - 5, y + h - 22);\n    ctx.moveTo(x + 28, y + h - 22);\n    ctx.lineTo(x + 28, y + 5);\n    ctx.stroke();\n    \n    ctx.fillStyle = '#64748b'; ctx.font = '8px sans-serif';\n    ctx.fillText('Vce (V)', x + w - 28, y + h - 8);\n    ctx.save(); ctx.translate(x + 10, y + h/2); ctx.rotate(-Math.PI/2);\n    ctx.fillText('Ic (mA)', 0, 0); ctx.restore();\n    \n    Ib_values.forEach((ibVal, idx) => {\n      ctx.strokeStyle = `hsl(${200 + idx * 28}, 70%, 58%)`;\n      ctx.lineWidth = 1.3;\n      ctx.beginPath();\n      for (let px = 0; px < w - 38; px++) {\n        const vce = (px / (w - 38)) * Vcc;\n        let ic = 0;\n        if (vce < 0.2) {\n          ic = (beta * ibVal / 1000) * (vce / 0.2);\n        } else {\n          ic = beta * ibVal / 1000;\n        }\n        const plotY = (y + h - 22) - (ic / (Vcc/(Rc+Re) * 1.2)) * (h - 32);\n        if (px === 0) ctx.moveTo(x + 28 + px, plotY);\n        else ctx.lineTo(x + 28 + px, plotY);\n      }\n      ctx.stroke();\n    });\n    \n    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);\n    ctx.beginPath();\n    ctx.moveTo(x + 28, y + h - 22 - (Ic_sat / (Vcc/(Rc+Re) * 1.2)) * (h - 32));\n    ctx.lineTo(x + 28 + ((Vce_cutoff/Vcc) * (w - 38)), y + h - 22);\n    ctx.stroke();\n    ctx.setLineDash([]);\n    \n    const opX = x + 28 + (Vce / Vcc) * (w - 38);\n    const opY = (y + h - 22) - (Ic / (Vcc/(Rc+Re) * 1.2)) * (h - 32);\n    ctx.fillStyle = '#fbbf24';\n    ctx.beginPath(); ctx.arc(opX, opY, 4.5, 0, Math.PI*2); ctx.fill();\n    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.arc(opX, opY, 7, 0, Math.PI*2); ctx.stroke();\n    \n    ctx.fillStyle = '#fbbf24'; ctx.font = '8px sans-serif'; ctx.textAlign = 'left';\n    ctx.fillText('Q-point', opX + 8, opY - 4);\n    ctx.fillText(`(${Vce.toFixed(1)}V, ${Ic.toFixed(2)}mA)`, opX + 8, opY + 8);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '8px sans-serif';\n    ctx.fillText('Load Line', x + 32, y + 22);\n  }\n  \n  function drawCircuitAnalysis(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, params: BjtParams, state: BjtState) {\n    const { topology } = params;\n    const { Av, Ai, Ap, Zin, Zout, Pdiss } = state;\n    \n    ctx.fillStyle = 'rgba(15, 23, 42, 0.95)';\n    ctx.fillRect(x, y, w, h);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(x, y, w, h);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('Circuit Analysis', x + w/2, y + 16);\n    \n    ctx.fillStyle = '#e2e8f0'; ctx.font = '11px monospace'; ctx.textAlign = 'left';\n    const col1 = x + 12;\n    const col2 = x + w/2 + 5;\n    const rowH = 22;\n    let row = y + 32;\n    \n    ctx.fillText(`Voltage Gain (Av): ${Math.abs(Av).toFixed(1)} V/V`, col1, row);\n    ctx.fillText(`Current Gain (Ai): ${Math.abs(Ai).toFixed(1)} A/A`, col2, row);\n    row += rowH;\n    ctx.fillText(`Power Gain (Ap): ${Ap.toFixed(1)} dB`, col1, row);\n    ctx.fillText(`Power Diss: ${Pdiss.toFixed(1)} mW`, col2, row);\n    row += rowH;\n    ctx.fillText(`Input Z (Zin): ${Zin.toFixed(2)} kΩ`, col1, row);\n    ctx.fillText(`Output Z (Zout): ${Zout.toFixed(2)} kΩ`, col2, row);\n    row += rowH;\n    ctx.fillText(`Phase Shift: ${topology === 'common-emitter' ? '180° (inverted)' : '0° (non-inverted)'}`, col1, row);\n    \n    ctx.fillStyle = '#4ade80'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText(`${topology.replace(/-/g, ' ').toUpperCase()} CONFIGURATION`, x + w/2, y + h - 8);\n  }\n  \n  function drawCurrentFlow(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, params: BjtParams, state: BjtState, t: number) {\n    const { Ib, Ic, Ie } = state;\n    \n    ctx.fillStyle = 'rgba(15, 23, 42, 0.95)';\n    ctx.fillRect(x, y, w, h);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(x, y, w, h);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('Current Flow Summary', x + w/2, y + 14);\n    \n    const pathW = w / 3;\n    \n    ctx.fillStyle = '#f87171'; ctx.font = 'bold 11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('BASE CURRENT (Ib)', x + pathW/2, y + 30);\n    ctx.fillStyle = '#f87171'; ctx.font = '10px sans-serif';\n    ctx.fillText(`${Ib.toFixed(1)} μA`, x + pathW/2, y + 44);\n    ctx.fillStyle = '#f87171';\n    const ibDots = Math.min(6, Math.max(0, Math.floor(Ib / 20)));\n    for (let i = 0; i < ibDots; i++) {\n      const progress = ((t * 0.5 + i / Math.max(ibDots, 1)) % 1);\n      ctx.beginPath(); ctx.arc(x + pathW/2 - 30 + progress * 60, y + 32, 3, 0, Math.PI*2); ctx.fill();\n    }\n    \n    ctx.fillStyle = '#60a5fa'; ctx.font = 'bold 11px sans-serif';\n    ctx.fillText('COLLECTOR CURRENT (Ic)', x + pathW + pathW/2, y + 30);\n    ctx.fillStyle = '#60a5fa'; ctx.font = '10px sans-serif';\n    ctx.fillText(`${Ic.toFixed(2)} mA`, x + pathW + pathW/2, y + 44);\n    ctx.fillStyle = '#60a5fa';\n    const icDots = Math.min(10, Math.max(0, Math.floor(Ic * 2)));\n    for (let i = 0; i < icDots; i++) {\n      const progress = ((t * 1.0 + i / Math.max(icDots, 1)) % 1);\n      ctx.beginPath(); ctx.arc(x + pathW + pathW/2 - 40 + progress * 80, y + 32, 3, 0, Math.PI*2); ctx.fill();\n    }\n    \n    ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 11px sans-serif';\n    ctx.fillText('EMITTER CURRENT (Ie)', x + 2*pathW + pathW/2, y + 30);\n    ctx.fillStyle = '#fbbf24'; ctx.font = '10px sans-serif';\n    ctx.fillText(`${Ie.toFixed(2)} mA`, x + 2*pathW + pathW/2, y + 44);\n    ctx.fillStyle = '#fbbf24';\n    const ieDots = Math.min(10, Math.max(0, Math.floor(Ie * 2)));\n    for (let i = 0; i < ieDots; i++) {\n      const progress = ((t * 1.0 + i / Math.max(ieDots, 1)) % 1);\n      ctx.beginPath(); ctx.arc(x + 2*pathW + pathW/2 - 40 + progress * 80, y + 32, 3, 0, Math.PI*2); ctx.fill();\n    }\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('KCL: Ie = Ib + Ic  (emitter current = base current + collector current)', x + w/2, y + h - 6);\n  }\n  \n  useEffect(() => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    if (!ctx) return;\n    \n    const animate = (timestamp: number) => {\n      timeRef.current = timestamp / 1000;\n      draw(ctx, timeRef.current);\n      animRef.current = requestAnimationFrame(animate);\n    };\n    \n    animRef.current = requestAnimationFrame(animate);\n    return () => cancelAnimationFrame(animRef.current);\n  }, [draw]);\n  \n  return (\n    <canvas\n      ref={canvasRef}\n      width={width}\n      height={height}\n      className=\"w-full h-auto rounded-lg border border-slate-700\"\n    />\n  );\n}", "src/components/simulation/PnJunctionCanvas.tsx": "// src/components/simulation/PnJunctionCanvas.tsx\n'use client';\n\nimport React, { useRef, useEffect, useCallback } from 'react';\nimport { computeJunctionState, MaterialParams, JunctionState } from '@/lib/physics/pnJunction';\n\ninterface PnJunctionCanvasProps {\n  params: MaterialParams;\n  width?: number;\n  height?: number;\n}\n\nexport default function PnJunctionCanvas({ params, width = 900, height = 600 }: PnJunctionCanvasProps) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const animRef = useRef<number>(0);\n  const timeRef = useRef<number>(0);\n  \n  const state = computeJunctionState(params);\n  \n  const draw = useCallback((ctx: CanvasRenderingContext2D, t: number) => {\n    // These circuit diagrams use a fixed logical layout. Scale the whole\n    // drawing, including labels, rather than clipping its fixed coordinates.\n    const actualW = ctx.canvas.width, actualH = ctx.canvas.height;\n    const W = 900, H = 600;\n    const scale = Math.min(actualW / W, actualH / H);\n    ctx.setTransform(1, 0, 0, 1, 0, 0);\n    ctx.clearRect(0, 0, actualW, actualH);\n    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, actualW, actualH);\n    ctx.setTransform(scale, 0, 0, scale, (actualW - W * scale) / 2, (actualH - H * scale) / 2);\n    const { Na, Nd, temperature, appliedBias, material, circuitMode, Vin, Rload, freq } = params;\n    const { Vbi, Wp, Wn, Wtotal, Emax, Id, Vd, Pout, efficiency, ripple, Vdc } = state;\n    \n    ctx.clearRect(0, 0, W, H);\n    ctx.fillStyle = '#0f172a';\n    ctx.fillRect(0, 0, W, H);\n    \n    const margin = 50;\n    const centerX = W / 2;\n    \n    if (circuitMode === 'diode') {\n      drawDiodeMode(ctx, W, H, margin, centerX, t);\n    } else {\n      drawRectifierMode(ctx, W, H, margin, centerX, t);\n    }\n    \n    ctx.fillStyle = 'rgba(15, 23, 42, 0.9)';\n    ctx.fillRect(margin, H - 55, 340, 42);\n    ctx.strokeStyle = '#334155';\n    ctx.strokeRect(margin, H - 55, 340, 42);\n    \n    ctx.fillStyle = '#e2e8f0';\n    ctx.font = '11px monospace';\n    ctx.textAlign = 'left';\n    ctx.fillText(`Vbi=${Vbi.toFixed(3)}V  Wdep=${Wtotal.toFixed(1)}nm  Id=${Id.toFixed(3)}mA`, margin + 8, H - 38);\n    ctx.fillText(`Emax=${(Emax/1e4).toFixed(1)}kV/cm  Pout=${Pout.toFixed(1)}mW  η=${efficiency.toFixed(1)}%`, margin + 8, H - 22);\n    \n    ctx.fillStyle = '#e2e8f0';\n    ctx.font = 'bold 15px sans-serif';\n    ctx.textAlign = 'center';\n    const modeLabel = circuitMode === 'diode' ? 'Diode Characteristic' : \n                      circuitMode === 'half-wave' ? 'Half-Wave Rectifier' : 'Full-Wave Bridge Rectifier';\n    ctx.fillText(`${material} PN Junction — ${modeLabel} @ ${temperature}K`, W / 2, 22);\n    \n  }, [params, state]);\n  \n  function drawDiodeMode(ctx: CanvasRenderingContext2D, W: number, H: number, margin: number, centerX: number, t: number) {\n    const { Na, Nd, appliedBias, material, temperature } = params;\n    const { Vbi, Wp, Wn, Wtotal, fermiLevelP, fermiLevelN } = state;\n    \n    const crossY = 70;\n    const crossH = 110;\n    const devW = 280;\n    const devStartX = centerX - devW / 2;\n    \n    ctx.fillStyle = '#1e3a5f';\n    ctx.fillRect(devStartX, crossY, devW / 2 - 2, crossH);\n    ctx.fillRect(devStartX + devW / 2 + 2, crossY, devW / 2 - 2, crossH);\n    \n    const maxW = 200;\n    const scaleW = Math.min(devW / 4 / maxW, 1);\n    const dispWp = Wp * scaleW;\n    const dispWn = Wn * scaleW;\n    \n    const depGrad = ctx.createLinearGradient(centerX - dispWp, 0, centerX + dispWn, 0);\n    depGrad.addColorStop(0, '#334155');\n    depGrad.addColorStop(0.5, '#475569');\n    depGrad.addColorStop(1, '#334155');\n    ctx.fillStyle = depGrad;\n    ctx.fillRect(centerX - dispWp, crossY, dispWp + dispWn, crossH);\n    \n    ctx.strokeStyle = '#94a3b8';\n    ctx.lineWidth = 2;\n    ctx.setLineDash([5, 5]);\n    ctx.beginPath();\n    ctx.moveTo(centerX, crossY - 8);\n    ctx.lineTo(centerX, crossY + crossH + 8);\n    ctx.stroke();\n    ctx.setLineDash([]);\n    \n    ctx.fillStyle = '#e2e8f0';\n    ctx.font = 'bold 12px sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('P-TYPE', devStartX + (devW/2 - dispWp)/2, crossY + crossH/2);\n    ctx.fillText('N-TYPE', centerX + dispWn + (devW/2 - dispWn)/2, crossY + crossH/2);\n    ctx.fillText('DEPLETION', centerX, crossY + crossH/2);\n    \n    ctx.fillStyle = '#f87171';\n    for (let i = 0; i < 6; i++) {\n      const x = centerX - dispWp + (dispWp/6)*i + dispWp/12;\n      for (let j = 0; j < 3; j++) {\n        ctx.fillRect(x - 3, crossY + 12 + j*32, 6, 1.5);\n      }\n    }\n    ctx.fillStyle = '#60a5fa';\n    for (let i = 0; i < 6; i++) {\n      const x = centerX + (dispWn/6)*i + dispWn/12;\n      for (let j = 0; j < 3; j++) {\n        ctx.fillRect(x - 3, crossY + 12 + j*32, 6, 1.5);\n        ctx.fillRect(x - 1, crossY + 10 + j*32, 1.5, 5);\n      }\n    }\n    \n    const holeCount = Math.min(Math.floor(Na/1e15), 25);\n    for (let i = 0; i < holeCount; i++) {\n      const bx = (i*137.3) % (devW/2 - dispWp - 16);\n      const by = (i*89.7) % (crossH - 16);\n      const x = devStartX + 8 + bx;\n      const y = crossY + 8 + by;\n      const drift = appliedBias > 0 ? Math.sin(t*2 + i)*3 : 0;\n      ctx.strokeStyle = '#f87171';\n      ctx.lineWidth = 1.2;\n      ctx.beginPath();\n      ctx.arc(x + drift, y, 4, 0, Math.PI*2);\n      ctx.stroke();\n      ctx.fillStyle = '#f87171';\n      ctx.font = '7px sans-serif';\n      ctx.fillText('+', x + drift, y + 2.5);\n    }\n    \n    const elecCount = Math.min(Math.floor(Nd/1e15), 25);\n    for (let i = 0; i < elecCount; i++) {\n      const bx = (i*151.7) % (devW/2 - dispWn - 16);\n      const by = (i*67.3) % (crossH - 16);\n      const x = centerX + dispWn + 8 + bx;\n      const y = crossY + 8 + by;\n      const drift = appliedBias > 0 ? Math.sin(t*2 + i + 1)*3 : 0;\n      ctx.fillStyle = '#60a5fa';\n      ctx.beginPath();\n      ctx.arc(x + drift, y, 3.5, 0, Math.PI*2);\n      ctx.fill();\n    }\n    \n    if (appliedBias > 0.1) {\n      ctx.strokeStyle = '#fbbf24';\n      ctx.lineWidth = 2;\n      const arrowCount = Math.min(Math.floor(appliedBias*5), 6);\n      for (let i = 0; i < arrowCount; i++) {\n        const progress = ((t*0.5 + i/arrowCount) % 1);\n        const hx = devStartX + (centerX + dispWn - devStartX)*progress;\n        const hy = crossY - 12 + (i%3)*8;\n        ctx.beginPath();\n        ctx.moveTo(hx - 8, hy); ctx.lineTo(hx, hy);\n        ctx.lineTo(hx - 3, hy - 2.5);\n        ctx.moveTo(hx, hy); ctx.lineTo(hx - 3, hy + 2.5);\n        ctx.stroke();\n      }\n    }\n    \n    const bandY = crossY + crossH + 35;\n    const bandH = 130;\n    const midBand = bandY + bandH/2;\n    const props = { Si: 1.12, Ge: 0.67, GaAs: 1.42 };\n    const Eg = props[material];\n    const scaleE = bandH / 2.5;\n    \n    ctx.strokeStyle = '#f87171';\n    ctx.lineWidth = 2;\n    ctx.beginPath();\n    ctx.moveTo(margin, midBand + fermiLevelP*scaleE + Eg*scaleE/2);\n    ctx.lineTo(centerX - dispWp, midBand + fermiLevelP*scaleE + Eg*scaleE/2);\n    ctx.bezierCurveTo(centerX - dispWp/2, midBand + fermiLevelP*scaleE + Eg*scaleE/2,\n                      centerX + dispWn/2, midBand + fermiLevelN*scaleE + Eg*scaleE/2,\n                      centerX + dispWn, midBand + fermiLevelN*scaleE + Eg*scaleE/2);\n    ctx.lineTo(W - margin, midBand + fermiLevelN*scaleE + Eg*scaleE/2);\n    ctx.stroke();\n    \n    ctx.strokeStyle = '#60a5fa';\n    ctx.beginPath();\n    ctx.moveTo(margin, midBand + fermiLevelP*scaleE - Eg*scaleE/2);\n    ctx.lineTo(centerX - dispWp, midBand + fermiLevelP*scaleE - Eg*scaleE/2);\n    ctx.bezierCurveTo(centerX - dispWp/2, midBand + fermiLevelP*scaleE - Eg*scaleE/2,\n                      centerX + dispWn/2, midBand + fermiLevelN*scaleE - Eg*scaleE/2,\n                      centerX + dispWn, midBand + fermiLevelN*scaleE - Eg*scaleE/2);\n    ctx.lineTo(W - margin, midBand + fermiLevelN*scaleE - Eg*scaleE/2);\n    ctx.stroke();\n    \n    ctx.strokeStyle = '#4ade80';\n    ctx.setLineDash([5, 4]);\n    ctx.beginPath();\n    ctx.moveTo(margin, midBand + fermiLevelP*scaleE);\n    ctx.lineTo(centerX - dispWp, midBand + fermiLevelP*scaleE);\n    ctx.bezierCurveTo(centerX - dispWp/2, midBand + (fermiLevelP+fermiLevelN)/2*scaleE,\n                      centerX + dispWn/2, midBand + (fermiLevelP+fermiLevelN)/2*scaleE,\n                      centerX + dispWn, midBand + fermiLevelN*scaleE);\n    ctx.lineTo(W - margin, midBand + fermiLevelN*scaleE);\n    ctx.stroke();\n    ctx.setLineDash([]);\n    \n    ctx.fillStyle = '#f87171'; ctx.font = '11px sans-serif'; ctx.textAlign = 'left';\n    ctx.fillText('Ev', margin + 4, midBand + fermiLevelP*scaleE + Eg*scaleE/2 - 4);\n    ctx.fillStyle = '#60a5fa';\n    ctx.fillText('Ec', margin + 4, midBand + fermiLevelP*scaleE - Eg*scaleE/2 - 4);\n    ctx.fillStyle = '#4ade80';\n    ctx.fillText('Ef', margin + 4, midBand + fermiLevelP*scaleE - 4);\n    \n    const ivX = W - margin - 200;\n    const ivY = crossY + 10;\n    const ivW = 190;\n    const ivH = 110;\n    \n    ctx.fillStyle = 'rgba(15,23,42,0.92)';\n    ctx.fillRect(ivX, ivY, ivW, ivH);\n    ctx.strokeStyle = '#475569'; ctx.lineWidth = 1;\n    ctx.strokeRect(ivX, ivY, ivW, ivH);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('I-V Characteristic', ivX + ivW/2, ivY + 12);\n    \n    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(ivX + 22, ivY + ivH - 18);\n    ctx.lineTo(ivX + ivW - 4, ivY + ivH - 18);\n    ctx.moveTo(ivX + 22, ivY + ivH - 18);\n    ctx.lineTo(ivX + 22, ivY + 5);\n    ctx.stroke();\n    \n    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1.8;\n    ctx.beginPath();\n    const VT = 0.0258 * (temperature/300);\n    const Js = 1e-12;\n    for (let px = 0; px < ivW - 30; px++) {\n      const v = (px/(ivW-30))*1.0 - 0.3;\n      const i = Js * (Math.exp(v/VT) - 1);\n      const plotI = Math.max(-1, Math.min(1, i/1e-3));\n      const py = (ivY + ivH - 18) - plotI*(ivH - 26)/2;\n      if (px === 0) ctx.moveTo(ivX + 22 + px, py);\n      else ctx.lineTo(ivX + 22 + px, py);\n    }\n    ctx.stroke();\n    \n    const opV = (appliedBias + 0.3)/1.0 * (ivW - 30);\n    const opI = Js * (Math.exp(appliedBias/VT) - 1);\n    const plotOpI = Math.max(-1, Math.min(1, opI/1e-3));\n    const opY = (ivY + ivH - 18) - plotOpI*(ivH - 26)/2;\n    ctx.fillStyle = '#fbbf24';\n    ctx.beginPath(); ctx.arc(ivX + 22 + opV, opY, 3.5, 0, Math.PI*2); ctx.fill();\n  }\n  \n  function drawRectifierMode(ctx: CanvasRenderingContext2D, W: number, H: number, margin: number, centerX: number, t: number) {\n    const { Vin, Rload, freq, circuitMode, material } = params;\n    const { Vdc, ripple, efficiency, Pout } = state;\n    \n    const omega = 2 * Math.PI * freq;\n    const vInstant = Vin * Math.sin(omega * t);\n    \n    const circY = 55;\n    const circH = 180;\n    \n    if (circuitMode === 'half-wave') {\n      drawHalfWaveCircuit(ctx, margin + 30, circY, circH, t, vInstant);\n    } else {\n      drawFullWaveCircuit(ctx, margin + 30, circY, circH, t, vInstant);\n    }\n    \n    const waveX = margin;\n    const waveY = circY + circH + 30;\n    const waveW = (W - margin*2) / 2 - 10;\n    const waveH = 100;\n    \n    ctx.fillStyle = 'rgba(15,23,42,0.9)';\n    ctx.fillRect(waveX, waveY, waveW, waveH);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(waveX, waveY, waveW, waveH);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('AC Input Voltage', waveX + waveW/2, waveY + 14);\n    \n    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 0.5;\n    for (let i = 1; i < 4; i++) {\n      const gy = waveY + i * waveH/4;\n      ctx.beginPath(); ctx.moveTo(waveX, gy); ctx.lineTo(waveX + waveW, gy); ctx.stroke();\n    }\n    \n    ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 2;\n    ctx.beginPath();\n    for (let px = 0; px < waveW; px++) {\n      const phase = (px/waveW) * 4 * Math.PI - t * omega * 0.3;\n      const amp = (Vin/15) * (waveH/2 - 10);\n      const py = waveY + waveH/2 - Math.sin(phase) * amp;\n      if (px === 0) ctx.moveTo(waveX + px, py);\n      else ctx.lineTo(waveX + px, py);\n    }\n    ctx.stroke();\n    \n    const markerPhase = -t * omega * 0.3;\n    const markerY = waveY + waveH/2 - Math.sin(markerPhase) * (Vin/15) * (waveH/2 - 10);\n    ctx.fillStyle = '#fbbf24';\n    ctx.beginPath(); ctx.arc(waveX + waveW/2, markerY, 4, 0, Math.PI*2); ctx.fill();\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';\n    ctx.fillText(`Vpeak = ${Vin.toFixed(1)}V`, waveX + 8, waveY + waveH - 8);\n    ctx.fillText(`f = ${freq}Hz`, waveX + waveW - 60, waveY + waveH - 8);\n    \n    const outX = waveX + waveW + 20;\n    const outW = waveW;\n    \n    ctx.fillStyle = 'rgba(15,23,42,0.9)';\n    ctx.fillRect(outX, waveY, outW, waveH);\n    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;\n    ctx.strokeRect(outX, waveY, outW, waveH);\n    \n    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('DC Output Voltage', outX + outW/2, waveY + 14);\n    \n    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 0.5;\n    for (let i = 1; i < 4; i++) {\n      const gy = waveY + i * waveH/4;\n      ctx.beginPath(); ctx.moveTo(outX, gy); ctx.lineTo(outX + outW, gy); ctx.stroke();\n    }\n    \n    ctx.strokeStyle = '#4ade80'; ctx.lineWidth = 2;\n    ctx.beginPath();\n    for (let px = 0; px < outW; px++) {\n      const phase = (px/outW) * 4 * Math.PI - t * omega * 0.3;\n      let vout = 0;\n      if (circuitMode === 'half-wave') {\n        const vin = Math.sin(phase);\n        vout = vin > 0 ? (Vin - 0.7) * vin : 0;\n      } else {\n        vout = (Vin - 0.7) * Math.abs(Math.sin(phase));\n      }\n      const amp = (1/15) * (waveH/2 - 10);\n      const py = waveY + waveH/2 - vout * amp;\n      if (px === 0) ctx.moveTo(outX + px, py);\n      else ctx.lineTo(outX + px, py);\n    }\n    ctx.stroke();\n    \n    ctx.strokeStyle = '#f87171'; ctx.setLineDash([4, 3]); ctx.lineWidth = 1.5;\n    const dcY = waveY + waveH/2 - Vdc * (1/15) * (waveH/2 - 10);\n    ctx.beginPath(); ctx.moveTo(outX, dcY); ctx.lineTo(outX + outW, dcY); ctx.stroke();\n    ctx.setLineDash([]);\n    \n    ctx.fillStyle = '#f87171'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';\n    ctx.fillText(`Vdc = ${Vdc.toFixed(2)}V`, outX + 8, dcY - 4);\n    \n    const flowY = waveY + waveH + 25;\n    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';\n    ctx.fillText('Current Flow Through Load', centerX, flowY + 12);\n    \n    const loadX = centerX - 60;\n    const loadW = 120;\n    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;\n    ctx.beginPath();\n    ctx.moveTo(loadX, flowY + 30);\n    for (let i = 0; i < 6; i++) {\n      ctx.lineTo(loadX + i*20 + 5, flowY + 22);\n      ctx.lineTo(loadX + i*20 + 15, flowY + 38);\n    }\n    ctx.lineTo(loadX + loadW, flowY + 30);\n    ctx.stroke();\n    \n    ctx.fillStyle = '#e2e8f0'; ctx.font = '10px sans-serif';\n    ctx.fillText(`Rload = ${Rload}Ω`, centerX, flowY + 52);\n    \n    const Ipeak = (Vin - 0.7) / Rload * 1000;\n    const Iinstant = circuitMode === 'half-wave' \n      ? (vInstant > 0 ? (vInstant - 0.7) / Rload * 1000 : 0)\n      : (Math.abs(vInstant) - 0.7) / Rload * 1000;\n    const dotCount = Math.max(0, Math.min(8, Math.floor(Iinstant / 2)));\n    \n    for (let i = 0; i < dotCount; i++) {\n      const progress = ((t * 2 + i / Math.max(dotCount, 1)) % 1);\n      const dx = loadX + progress * loadW;\n      ctx.fillStyle = '#fbbf24';\n      ctx.beginPath(); ctx.arc(dx, flowY + 30, 3, 0, Math.PI*2); ctx.fill();\n    }\n    \n    ctx.fillStyle = 'rgba(15,23,42,0.9)';\n    ctx.fillRect(margin, flowY + 60, 280, 55);\n    ctx.strokeStyle = '#334155'; ctx.strokeRect(margin, flowY + 60, 280, 55);\n    \